import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    proxy: {
      "/api": "http://localhost:3002",
    },
  },
  build: {
    outDir: "dist",
    sourcemap: false,
  },
});

export type TaskStatus =
  | "QUEUED"
  | "RUNNING"
  | "COMPLETED"
  | "FAILED"
  | "AWAITING_APPROVAL";

export type TaskType = "PROSPECT_RESEARCH" | "OUTREACH_DRAFT";

export type TaskEventKind = "STATUS" | "PROGRESS" | "LOG" | "DELIVERY" | "ERROR";

export interface TaskEvent {
  id: string;
  at: string;
  kind: TaskEventKind;
  message: string;
  status?: TaskStatus;
}

export interface ResearchInput {
  city: string;
  category: "cafe" | "restaurant" | "bakery";
  count: number;
}

export interface SourceReference {
  id: string;
  kind: "OPENSTREETMAP" | "NOMINATIM" | "WEBSITE" | "HTTP_HEADER" | "SYSTEM";
  title: string;
  url: string;
  publisher: string;
  retrievedAt: string;
  excerpt: string;
  contentHash?: string;
}

export interface Location {
  address: string;
  city: string;
  country: string;
  lat: number;
  lon: number;
}

export interface WebsiteAudit {
  viewport: boolean;
  metaDescription: string | null;
  h1: string | null;
  socialLinks: string[];
  bookingLinks: string[];
  structuredData: boolean;
  copyrightYear: number | null;
  generator: string | null;
  forms: number;
  phoneLinks: number;
  pageBytes: number;
  contentType: string | null;
  serverHeader: string | null;
  titleMatch: "STRONG" | "PARTIAL" | "NONE";
}

export interface WebsiteFinding {
  url: string | null;
  domain: string | null;
  verification: "PAGE_VERIFIED" | "TAG_ONLY" | "UNREACHABLE" | "NOT_PROVIDED";
  httpStatus: number | null;
  finalUrl: string | null;
  https: boolean;
  title: string | null;
  description: string | null;
  responseMs: number | null;
  contentHash: string | null;
  audit: WebsiteAudit | null;
  notes: string[];
}

export type OpportunityLevel = "HIGH" | "MEDIUM" | "LOW";

export interface OpportunitySignal {
  code: string;
  label: string;
  impact: number;
  evidence: string;
  sourceRefs: string[];
}

export interface Opportunity {
  level: OpportunityLevel;
  score: number;
  summary: string;
  signals: OpportunitySignal[];
}

export interface ResearchFact {
  statement: string;
  sourceRefs: string[];
}

export interface Prospect {
  id: string;
  rank: number;
  businessName: string;
  category: string;
  location: Location;
  osm: {
    type: string;
    id: number;
    url: string;
  };
  website: WebsiteFinding;
  opportunity: Opportunity;
  facts: ResearchFact[];
  assumptions: string[];
  sources: SourceReference[];
  researchTimestamp: string;
}

export interface ResearchResult {
  assignment: {
    city: string;
    category: string;
    requestedCount: number;
    deliveredCount: number;
  };
  prospects: Prospect[];
  methodology: string[];
  limitations: string[];
  sources: SourceReference[];
  executedAt: string;
  provider: string;
  candidatesExamined: number;
  websitesAudited: number;
}

export interface OutreachDraftResult {
  prospectId: string;
  businessName: string;
  draft: {
    subject: string;
    body: string;
    channel: "email";
  };
  approval: {
    status: "PENDING" | "APPROVED" | "REJECTED";
    requestedAt: string;
    decidedAt: string | null;
    note: string | null;
  };
  sent: false;
  note: string;
}

export interface DeliveryProof {
  persisted: boolean;
  persistedAt: string | null;
  readbackVerified: boolean;
  verifiedAt: string | null;
  broadcastClients: number;
  apiPath: string;
}

export interface TaskError {
  code: string;
  message: string;
  detail: string | null;
  at: string;
  retryable: boolean;
}

export interface Task {
  id: string;
  type: TaskType;
  title: string;
  brief: string;
  input: ResearchInput | { prospectId: string; parentTaskId: string };
  status: TaskStatus;
  createdAt: string;
  updatedAt: string;
  startedAt: string | null;
  completedAt: string | null;
  progress: {
    stage: string;
    message: string;
    percent: number;
  };
  events: TaskEvent[];
  execution: {
    provider: string;
    mode: "LIVE" | "TEST";
    attemptedPasses: number;
  };
  result: ResearchResult | OutreachDraftResult | null;
  error: TaskError | null;
  approval: {
    status: "PENDING" | "APPROVED" | "REJECTED";
    requestedAt: string;
    decidedAt: string | null;
    note: string | null;
    scope: string;
  } | null;
  delivery: DeliveryProof;
}

export interface CreateResearchRequest {
  city: string;
  category: "cafe" | "restaurant" | "bakery";
  count?: number;
}

export interface CreateOutreachRequest {
  parentTaskId: string;
  prospectId: string;
}

export interface DecisionRequest {
  decision: "APPROVE" | "REJECT";
  note?: string;
}

export interface ApiError {
  error: {
    code: string;
    message: string;
    detail?: string | null;
  };
}

export interface SystemStatus {
  mode: "LIVE";
  version: string;
  startedAt: string;
  researchProvider: string;
  approvalPolicy: string;
  connectedClients: number;
  taskCounts: Record<TaskStatus, number>;
  capabilities: Array<{
    id: string;
    label: string;
    status: "LIVE" | "STANDBY" | "BLOCKED";
    detail: string;
  }>;
}

import { randomUUID } from "node:crypto";

export function taskId(): string {
  return `TSK-${randomUUID().split("-")[0].toUpperCase()}`;
}

export function eventId(): string {
  return `EVT-${randomUUID().split("-")[0].toUpperCase()}`;
}

export function prospectId(index: number): string {
  return `PRS-${String(index + 1).padStart(2, "0")}-${randomUUID()
    .split("-")[0]
    .toUpperCase()}`;
}

export function nowIso(): string {
  return new Date().toISOString();
}

import { promises as fs } from "node:fs";
import path from "node:path";
import type { Task } from "../shared/types.ts";

interface PersistedState {
  version: 1;
  tasks: Task[];
}

/**
 * File-backed task store. Writes are serialized and atomic (write + rename).
 * A null file path creates an in-memory store for tests.
 */
export class TaskStore {
  private tasks = new Map<string, Task>();
  private writeChain: Promise<void> = Promise.resolve();
  private loaded = false;

  constructor(private readonly filePath: string | null) {}

  async init(): Promise<void> {
    if (this.loaded) return;
    this.loaded = true;
    if (!this.filePath) return;
    try {
      const raw = await fs.readFile(this.filePath, "utf8");
      const parsed = JSON.parse(raw) as PersistedState;
      if (parsed.version !== 1 || !Array.isArray(parsed.tasks)) {
        throw new Error("Unsupported HQ state file format");
      }
      for (const task of parsed.tasks) this.tasks.set(task.id, task);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
      await fs.mkdir(path.dirname(this.filePath), { recursive: true });
      await this.persist();
    }
  }

  list(): Task[] {
    return [...this.tasks.values()].sort((a, b) =>
      b.createdAt.localeCompare(a.createdAt),
    );
  }

  get(id: string): Task | null {
    return this.tasks.get(id) ?? null;
  }

  async upsert(task: Task): Promise<Task> {
    this.tasks.set(task.id, structuredClone(task));
    await this.persist();
    return structuredClone(task);
  }

  async readFromDisk(id: string): Promise<Task | null> {
    if (!this.filePath) {
      const task = this.tasks.get(id);
      return task ? structuredClone(task) : null;
    }
    await this.writeChain;
    const raw = await fs.readFile(this.filePath, "utf8");
    const parsed = JSON.parse(raw) as PersistedState;
    return parsed.tasks.find((task) => task.id === id) ?? null;
  }

  private persist(): Promise<void> {
    const snapshot: PersistedState = {
      version: 1,
      tasks: this.list(),
    };
    this.writeChain = this.writeChain.then(async () => {
      if (!this.filePath) return;
      await fs.mkdir(path.dirname(this.filePath), { recursive: true });
      const tmp = `${this.filePath}.${process.pid}.tmp`;
      await fs.writeFile(tmp, JSON.stringify(snapshot, null, 2), "utf8");
      await fs.rename(tmp, this.filePath);
    });
    return this.writeChain;
  }
}

