import type {
  Opportunity,
  OpportunityLevel,
  OpportunitySignal,
  WebsiteAudit,
  WebsiteFinding,
} from "../../shared/types.ts";

const SOCIAL_HOSTS = [
  "facebook.com",
  "instagram.com",
  "twitter.com",
  "x.com",
  "linkedin.com",
  "tiktok.com",
  "youtube.com",
  "pinterest.com",
];

const BOOKING_HOSTS = [
  "resy.com",
  "opentable.",
  "sevenrooms.com",
  "tock.com",
  "calendly.com",
  "bookings.",
  "booking.",
  "square.site",
  "squareup.com",
  "toasttab.com",
  "whenworks.com",
  "simplybook.me",
];

const BOOKING_WORDS =
  /(book(?:ing)?|reserv(?:e|ation)|appointment|schedule|order online|buy online)/i;

export function decodeEntities(input: string): string {
  const named: Record<string, string> = {
    amp: "&",
    lt: "<",
    gt: ">",
    quot: '"',
    apos: "'",
    nbsp: " ",
    mdash: "—",
    ndash: "–",
    hellip: "…",
    rsquo: "’",
    lsquo: "‘",
    ldquo: "“",
    rdquo: "”",
  };
  return input
    .replace(/&#(\d+);/g, (_, code: string) =>
      String.fromCodePoint(Number(code)),
    )
    .replace(/&#x([0-9a-f]+);/gi, (_, code: string) =>
      String.fromCodePoint(Number.parseInt(code, 16)),
    )
    .replace(/&([a-z]+);/gi, (match, name: string) =>
      named[name.toLowerCase()] ?? match,
    );
}

export function stripTags(input: string): string {
  return decodeEntities(
    input
      .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
      .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
      .replace(/<[^>]+>/g, " "),
  )
    .replace(/\s+/g, " ")
    .trim();
}

export function extractTitle(html: string): string | null {
  const match = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const title = match ? stripTags(match[1]) : "";
  return title || null;
}

export function extractMeta(
  html: string,
  name: string,
): string | null {
  const tags = html.match(/<meta\b[^>]*>/gi) ?? [];
  for (const tag of tags) {
    const keys = [...tag.matchAll(/(?:name|property)\s*=\s*["']([^"']+)["']/gi)];
    if (!keys.some((key) => key[1].toLowerCase() === name.toLowerCase())) {
      continue;
    }
    const content = tag.match(/content\s*=\s*["']([\s\S]*?)["']/i);
    if (content) {
      const value = decodeEntities(content[1]).trim();
      if (value) return value;
    }
  }
  return null;
}

export function extractH1(html: string): string | null {
  const match = html.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i);
  const heading = match ? stripTags(match[1]) : "";
  return heading || null;
}

export function extractLinks(
  html: string,
): Array<{ href: string; text: string }> {
  const links: Array<{ href: string; text: string }> = [];
  for (const match of html.matchAll(/<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)) {
    links.push({ href: decodeEntities(match[1]), text: stripTags(match[2]) });
  }
  return links;
}

function isSocial(url: string): boolean {
  const lower = url.toLowerCase();
  return SOCIAL_HOSTS.some((host) => lower.includes(host));
}

function isBooking(link: { href: string; text: string }): boolean {
  const lower = link.href.toLowerCase();
  return (
    BOOKING_HOSTS.some((host) => lower.includes(host)) ||
    BOOKING_WORDS.test(link.text) ||
    /(book|reserv|appointment|schedule)/i.test(lower)
  );
}

function normalizeName(input: string): string {
  return input
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function nameMatch(
  businessName: string,
  title: string | null,
  h1: string | null,
  body: string,
): "STRONG" | "PARTIAL" | "NONE" {
  const target = normalizeName(businessName);
  if (!target) return "NONE";
  const haystack = `${normalizeName(title ?? "")} ${normalizeName(h1 ?? "")}`;
  if (haystack.includes(target)) return "STRONG";
  const targetTokens = target.split(" ").filter((token) => token.length > 2);
  if (targetTokens.length === 0) return "NONE";
  const bodyNorm = ` ${normalizeName(body)} `;
  const matched = targetTokens.filter((token) => bodyNorm.includes(token)).length;
  if (matched / targetTokens.length >= 0.6) return "PARTIAL";
  return "NONE";
}

export function auditHtml(
  html: string,
  businessName: string,
  contentType: string | null,
  serverHeader: string | null,
  pageBytes: number,
): WebsiteAudit {
  const links = extractLinks(html);
  const socialLinks = [
    ...new Set(links.filter((link) => isSocial(link.href)).map((link) => link.href)),
  ].slice(0, 12);
  const bookingLinks = [
    ...new Set(
      links
        .filter((link) => isBooking(link))
        .filter((link) => !isSocial(link.href))
        .map((link) => link.href),
    ),
  ].slice(0, 8);

  const copyrightMatches = [
    ...html.matchAll(/(?:©|&copy;|copyright)[^0-9]{0,24}(20\d{2})/gi),
  ].map((match) => Number(match[1]));
  const plausible = copyrightMatches.filter(
    (year) => year >= 2000 && year <= new Date().getFullYear() + 1,
  );
  const title = extractTitle(html);
  const h1 = extractH1(html);
  const bodyText = stripTags(html);

  const generatorTag = (html.match(
    /<meta\b[^>]*name\s*=\s*["']generator["'][^>]*content\s*=\s*["']([^"']+)["']/i,
  ) ?? html.match(
    /<meta\b[^>]*content\s*=\s*["']([^"']+)["'][^>]*name\s*=\s*["']generator["']/i,
  ))?.[1] ?? null;

  return {
    viewport: /<meta\b[^>]*name\s*=\s*["']viewport["']/i.test(html),
    metaDescription: extractMeta(html, "description"),
    h1,
    socialLinks,
    bookingLinks,
    structuredData: /application\/ld\+json/i.test(html),
    copyrightYear: plausible.length ? Math.max(...plausible) : null,
    generator: generatorTag ? decodeEntities(generatorTag).trim() : null,
    forms: (html.match(/<form\b/gi) ?? []).length,
    phoneLinks: (html.match(/href\s*=\s*["']tel:/gi) ?? []).length,
    pageBytes,
    contentType,
    serverHeader,
    titleMatch: nameMatch(businessName, title, h1, bodyText),
  };
}

export function opportunityLevel(score: number): OpportunityLevel {
  if (score >= 50) return "HIGH";
  if (score >= 25) return "MEDIUM";
  return "LOW";
}

export function buildOpportunity(
  website: WebsiteFinding,
  responseMs: number | null,
  refs: { website: string; osm: string },
  currentYear = new Date().getFullYear(),
): Opportunity {
  const signals: OpportunitySignal[] = [];
  const add = (
    code: string,
    label: string,
    impact: number,
    evidence: string,
    sourceRefs: string[] = [refs.website],
  ) => signals.push({ code, label, impact, evidence, sourceRefs });

  if (website.verification === "UNREACHABLE") {
    add(
      "WEBSITE_UNREACHABLE",
      "Official website did not return a usable page",
      60,
      website.notes[0] ?? "The website could not be fetched during this audit.",
      [refs.website, refs.osm],
    );
  } else if (website.verification === "NOT_PROVIDED") {
    add(
      "NO_WEBSITE_TAG",
      "No official website recorded in the public directory listing",
      45,
      "OpenStreetMap has no website or contact:website tag for this business.",
      [refs.osm],
    );
  } else if (website.verification === "TAG_ONLY") {
    add(
      "WEBSITE_TAG_ONLY",
      "Website address exists but the page could not be verified",
      35,
      website.notes[0] ?? "Only the directory tag was available.",
      [refs.website, refs.osm],
    );
  }

  const audit = website.audit;
  if (audit) {
    if (!website.https) {
      add("NO_HTTPS", "No HTTPS on the audited URL", 20, "The audited URL uses plain HTTP.");
    }
    if (!audit.viewport) {
      add(
        "NO_VIEWPORT",
        "No mobile viewport meta tag",
        25,
        "The homepage HTML does not declare a responsive viewport.",
      );
    }
    if (!audit.metaDescription) {
      add(
        "NO_META_DESCRIPTION",
        "Missing meta description",
        15,
        "The homepage has no meta description, weakening search snippets.",
      );
    }
    if (audit.bookingLinks.length === 0) {
      add(
        "NO_ONLINE_BOOKING",
        "No online booking or ordering path detected",
        10,
        "No reservation, booking, appointment, or online-order link was found on the homepage.",
      );
    }
    if (audit.copyrightYear !== null && audit.copyrightYear < currentYear - 1) {
      add(
        "STALE_COPYRIGHT",
        "Outdated copyright year",
        12,
        `The footer copyright year is ${audit.copyrightYear}.`,
      );
    }
    if (audit.socialLinks.length === 0) {
      add(
        "NO_SOCIAL_LINKS",
        "No social profiles linked",
        8,
        "No links to major social platforms were found on the homepage.",
      );
    }
    if (responseMs !== null && responseMs > 2500) {
      add(
        "SLOW_RESPONSE",
        "Slow homepage response",
        10,
        `The homepage took ${Math.round(responseMs)} ms to respond.`,
      );
    }
    if (!audit.structuredData) {
      add(
        "NO_STRUCTURED_DATA",
        "No structured business data",
        8,
        "No JSON-LD structured data block was found on the homepage.",
      );
    }
    if (audit.pageBytes > 500_000) {
      add(
        "LARGE_PAGE",
        "Large homepage payload",
        5,
        `The HTML payload was ${Math.round(audit.pageBytes / 1024)} KB.`,
      );
    }
    if (audit.titleMatch === "NONE") {
      add(
        "IDENTITY_UNCLEAR",
        "Business name not confirmed in page title or heading",
        15,
        "The website loaded, but its title and main heading did not contain the listed business name.",
        [refs.website, refs.osm],
      );
    }
  }

  const rawScore = signals.reduce((total, signal) => total + signal.impact, 0);
  const score = Math.min(100, rawScore);
  const level = opportunityLevel(score);
  const top = [...signals]
    .sort((a, b) => b.impact - a.impact)
    .slice(0, 3)
    .map((signal) => signal.label.toLowerCase());

  const summary = top.length
    ? `Observed technical refresh opportunity: ${top.join("; ")}.`
    : "No material technical opportunity was detected in the homepage audit.";

  return { level, score, summary, signals };
}

import { lookup } from "node:dns/promises";
import { isIP } from "node:net";

export const RESEARCH_USER_AGENT =
  "AgentHQResearch/2.0 (DEEMANNIE'S DIGITAL; prospect research; +https://github.com/dannyleonards42-web/PlayGround)";

const MAX_BODY_BYTES = 1_500_000;
const MAX_REDIRECTS = 5;

export class FetchSafetyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "FetchSafetyError";
  }
}

export function isPrivateAddress(address: string): boolean {
  const version = isIP(address);
  if (version === 4) {
    const parts = address.split(".").map(Number);
    const [a, b] = parts;
    if (a === 0 || a === 10 || a === 127) return true;
    if (a === 169 && b === 254) return true;
    if (a === 172 && b >= 16 && b <= 31) return true;
    if (a === 192 && b === 168) return true;
    if (a === 100 && b >= 64 && b <= 127) return true;
    if (a === 198 && (b === 18 || b === 19)) return true;
    if (a >= 224) return true;
    return false;
  }
  if (version === 6) {
    const normalized = address.toLowerCase();
    if (normalized === "::" || normalized === "::1") return true;
    if (normalized.startsWith("fc") || normalized.startsWith("fd")) return true;
    if (
      normalized.startsWith("fe8") ||
      normalized.startsWith("fe9") ||
      normalized.startsWith("fea") ||
      normalized.startsWith("feb")
    ) {
      return true;
    }
    if (normalized.startsWith("::ffff:")) {
      return isPrivateAddress(normalized.slice(7));
    }
    return false;
  }
  return true;
}

async function assertSafeUrl(raw: string): Promise<URL> {
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    throw new FetchSafetyError(`Invalid URL: ${raw}`);
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") {
    throw new FetchSafetyError(`Unsupported protocol: ${url.protocol}`);
  }
  if (url.username || url.password) {
    throw new FetchSafetyError("URLs with embedded credentials are not allowed");
  }
  const hostname = url.hostname.toLowerCase();
  if (
    hostname === "localhost" ||
    hostname.endsWith(".localhost") ||
    hostname.endsWith(".local")
  ) {
    throw new FetchSafetyError(`Local hostnames are not allowed: ${hostname}`);
  }
  if (isIP(hostname)) {
    if (isPrivateAddress(hostname)) {
      throw new FetchSafetyError(`Private address is not allowed: ${hostname}`);
    }
    return url;
  }
  let addresses: Array<{ address: string }>;
  try {
    addresses = await lookup(hostname, { all: true });
  } catch {
    throw new FetchSafetyError(`DNS lookup failed for ${hostname}`);
  }
  if (addresses.length === 0 || addresses.some((entry) => isPrivateAddress(entry.address))) {
    throw new FetchSafetyError(`Host resolves to a non-public address: ${hostname}`);
  }
  return url;
}

async function readCapped(
  response: Response,
  limit: number,
): Promise<{ text: string; bytes: number; truncated: boolean }> {
  if (!response.body) return { text: "", bytes: 0, truncated: false };
  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  let truncated = false;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    if (!value) continue;
    total += value.byteLength;
    if (total > limit) {
      const remaining = Math.max(0, limit - (total - value.byteLength));
      chunks.push(value.subarray(0, remaining));
      truncated = true;
      await reader.cancel();
      break;
    }
    chunks.push(value);
  }
  const merged = Buffer.concat(chunks.map((chunk) => Buffer.from(chunk)));
  return {
    text: merged.toString("utf8"),
    bytes: total,
    truncated,
  };
}

export interface SafeFetchResult {
  status: number;
  finalUrl: string;
  headers: Headers;
  bodyText: string;
  bytes: number;
  truncated: boolean;
  responseMs: number;
}

/**
 * Fetches a public HTTP(S) page with redirect validation, a body cap, and a
 * total timeout. Private/local targets are rejected before each hop.
 */
export async function safeFetch(
  rawUrl: string,
  timeoutMs = 15_000,
): Promise<SafeFetchResult> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  const started = performance.now();
  try {
    let current = await assertSafeUrl(rawUrl);
    let response: Response | null = null;
    for (let hop = 0; hop <= MAX_REDIRECTS; hop += 1) {
      response = await fetch(current, {
        redirect: "manual",
        signal: controller.signal,
        headers: {
          "user-agent": RESEARCH_USER_AGENT,
          accept: "text/html,application/xhtml+xml;q=0.9,*/*;q=0.5",
          "accept-language": "en-GB,en;q=0.9",
        },
      });
      if (response.status >= 300 && response.status < 400) {
        const location = response.headers.get("location");
        if (!location) break;
        current = await assertSafeUrl(new URL(location, current).toString());
        continue;
      }
      break;
    }
    if (!response) throw new Error("No response received");
    const contentType = response.headers.get("content-type");
    const isHtml =
      !contentType ||
      /text\/html|application\/xhtml\+xml/i.test(contentType);
    const body = isHtml
      ? await readCapped(response, MAX_BODY_BYTES)
      : { text: "", bytes: 0, truncated: false };
    return {
      status: response.status,
      finalUrl: response.url || current.toString(),
      headers: response.headers,
      bodyText: body.text,
      bytes: body.bytes,
      truncated: body.truncated,
      responseMs: performance.now() - started,
    };
  } finally {
    clearTimeout(timer);
  }
}

import { createHash } from "node:crypto";
import type {
  Prospect,
  ResearchFact,
  ResearchInput,
  ResearchResult,
  SourceReference,
  WebsiteFinding,
} from "../../shared/types.ts";
import { buildOpportunity, auditHtml } from "./extract.ts";
import { RESEARCH_USER_AGENT, safeFetch } from "./http.ts";
import { prospectId } from "../ids.ts";

export class ResearchExecutionError extends Error {
  constructor(
    readonly code: string,
    message: string,
    readonly detail: string | null = null,
    readonly retryable = true,
  ) {
    super(message);
    this.name = "ResearchExecutionError";
  }
}

export interface ResearchContext {
  onProgress: (stage: string, message: string, percent: number) => Promise<void>;
}

export interface ResearchProvider {
  readonly name: string;
  execute(
    input: ResearchInput,
    context: ResearchContext,
  ): Promise<ResearchResult>;
}

interface NominatimResult {
  display_name: string;
  lat: string;
  lon: string;
  boundingbox: [string, string, string, string];
  address?: Record<string, string>;
}

interface OverpassElement {
  type: string;
  id: number;
  lat?: number;
  lon?: number;
  center?: { lat: number; lon: number };
  tags?: Record<string, string>;
}

const CATEGORY_LABEL: Record<ResearchInput["category"], string> = {
  cafe: "café",
  restaurant: "restaurant",
  bakery: "bakery",
};

const CATEGORY_QUERY: Record<ResearchInput["category"], string> = {
  cafe: '["amenity"="cafe"]',
  restaurant: '["amenity"="restaurant"]',
  bakery: '["shop"="bakery"]',
};

const SOCIAL_DOMAINS = [
  "facebook.com",
  "instagram.com",
  "twitter.com",
  "x.com",
  "linkedin.com",
  "tiktok.com",
];

async function fetchJson<T>(url: string, init?: RequestInit): Promise<T> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 45_000);
  try {
    const response = await fetch(url, {
      ...init,
      signal: controller.signal,
      headers: {
        "user-agent": RESEARCH_USER_AGENT,
        accept: "application/json",
        ...(init?.headers ?? {}),
      },
    });
    if (!response.ok) {
      throw new ResearchExecutionError(
        "UPSTREAM_HTTP_ERROR",
        `Open data service returned HTTP ${response.status}.`,
        `Request to ${url} failed with status ${response.status}.`,
      );
    }
    return (await response.json()) as T;
  } catch (error) {
    if (error instanceof ResearchExecutionError) throw error;
    throw new ResearchExecutionError(
      "UPSTREAM_UNAVAILABLE",
      "A required open-data service could not be reached.",
      error instanceof Error ? error.message : String(error),
    );
  } finally {
    clearTimeout(timer);
  }
}

function normalizeWebsite(raw: string): string | null {
  const value = raw.trim();
  if (!value) return null;
  const withScheme = value.startsWith("//")
    ? `https:${value}`
    : /^https?:\/\//i.test(value)
      ? value
      : `https://${value}`;
  try {
    const url = new URL(withScheme);
    if (!/^https?:$/.test(url.protocol) || !url.hostname.includes(".")) {
      return null;
    }
    return url.toString();
  } catch {
    return null;
  }
}

function isSocialUrl(url: string): boolean {
  const lower = url.toLowerCase();
  return SOCIAL_DOMAINS.some((domain) => lower.includes(domain));
}

function addressFromTags(tags: Record<string, string>): string {
  const street = [tags["addr:housenumber"], tags["addr:street"]]
    .filter(Boolean)
    .join(" ")
    .trim();
  const parts = [
    street,
    tags["addr:unit"],
    tags["addr:postcode"],
  ].filter(Boolean);
  return parts.length
    ? parts.join(", ")
    : "Street address not tagged in OpenStreetMap";
}

function excerptForWebsite(
  finding: WebsiteFinding,
  httpStatus: number | null,
  serverHeader: string | null,
): string {
  if (finding.notes.length && finding.verification !== "PAGE_VERIFIED") {
    return finding.notes.join(" ").slice(0, 400);
  }
  const parts = [
    httpStatus ? `HTTP ${httpStatus}.` : "",
    finding.title ? `Title: ${finding.title}.` : "",
    finding.description ? `Description: ${finding.description}` : "",
    serverHeader ? `Server: ${serverHeader}.` : "",
  ].filter(Boolean);
  return parts.join(" ").slice(0, 500);
}

async function mapWithConcurrency<T, R>(
  items: T[],
  limit: number,
  mapper: (item: T, index: number) => Promise<R>,
): Promise<R[]> {
  const results = new Array<R>(items.length);
  let cursor = 0;
  async function worker(): Promise<void> {
    while (cursor < items.length) {
      const index = cursor;
      cursor += 1;
      results[index] = await mapper(items[index], index);
    }
  }
  await Promise.all(
    Array.from({ length: Math.min(limit, items.length) }, () => worker()),
  );
  return results;
}

interface Candidate {
  element: OverpassElement;
  name: string;
  websiteRaw: string | null;
  socialOnly: boolean;
}

export class LiveResearchProvider implements ResearchProvider {
  readonly name = "openstreetmap+nominatim+http-audit";

  async execute(
    input: ResearchInput,
    context: ResearchContext,
  ): Promise<ResearchResult> {
    const executedAt = new Date().toISOString();
    const label = CATEGORY_LABEL[input.category];

    await context.onProgress(
      "GEOCODE",
      `Resolving ${input.city} with Nominatim…`,
      5,
    );
    const cityUrl = `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(
      input.city,
    )}&format=jsonv2&addressdetails=1&limit=1`;
    const cityResults = await fetchJson<NominatimResult[]>(cityUrl, {
      headers: { accept: "application/json" },
    });
    const city = cityResults[0];
    if (!city) {
      throw new ResearchExecutionError(
        "CITY_NOT_FOUND",
        `No location matched “${input.city}”.`,
        "Nominatim returned zero results. Try a more specific city and country.",
        false,
      );
    }
    const [south, north, west, east] = city.boundingbox.map(Number);
    if ([south, north, west, east].some((value) => !Number.isFinite(value))) {
      throw new ResearchExecutionError(
        "CITY_BOUNDS_INVALID",
        "The city lookup returned unusable coordinates.",
        `Bounding box: ${city.boundingbox.join(", ")}`,
      );
    }
    const citySource: SourceReference = {
      id: "SRC-CITY",
      kind: "NOMINATIM",
      title: `Nominatim geocoding result for ${input.city}`,
      url: cityUrl,
      publisher: "OpenStreetMap / Nominatim",
      retrievedAt: executedAt,
      excerpt: `${city.display_name} — bounding box ${city.boundingbox.join(", ")}`,
    };

    await context.onProgress(
      "DIRECTORY_QUERY",
      `Searching OpenStreetMap for ${label}s with a listed website…`,
      15,
    );
    const filter = CATEGORY_QUERY[input.category];
    const bbox = `${south},${west},${north},${east}`;
    const query = `[out:json][timeout:45];
(
  nwr${filter}["website"](${bbox});
  nwr${filter}["contact:website"](${bbox});
);
out center tags 100;`;
    const overpassUrl = "https://overpass-api.de/api/interpreter";
    const overpass = await fetchJson<{ elements: OverpassElement[] }>(
      overpassUrl,
      {
        method: "POST",
        headers: { "content-type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({ data: query }).toString(),
      },
    );

    const seenNames = new Set<string>();
    const seenDomains = new Set<string>();
    const candidates: Candidate[] = [];
    for (const element of overpass.elements) {
      const tags = element.tags ?? {};
      const name = (tags.name ?? tags["name:en"] ?? "").trim();
      if (!name) continue;
      const nameKey = name.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
      if (seenNames.has(nameKey)) continue;
      const raw = tags.website ?? tags["contact:website"] ?? null;
      const normalized = raw ? normalizeWebsite(raw) : null;
      if (normalized) {
        try {
          const domain = new URL(normalized).hostname.replace(/^www\./, "");
          if (seenDomains.has(domain)) continue;
          seenDomains.add(domain);
        } catch {
          continue;
        }
      }
      seenNames.add(nameKey);
      candidates.push({
        element,
        name,
        websiteRaw: normalized,
        socialOnly: normalized ? isSocialUrl(normalized) : false,
      });
      if (candidates.length >= 14) break;
    }

    if (candidates.length === 0) {
      throw new ResearchExecutionError(
        "NO_CANDIDATES",
        `No ${label}s with a listed website were found inside the ${input.city} boundary.`,
        "OpenStreetMap returned no matching businesses with website tags. Try another category or city.",
        false,
      );
    }

    await context.onProgress(
      "WEBSITE_AUDIT",
      `Auditing ${candidates.length} candidate homepages. No messages will be sent.`,
      30,
    );

    let audited = 0;
    const auditedCandidates = await mapWithConcurrency(
      candidates,
      3,
      async (candidate) => {
        const finding = await this.auditWebsite(candidate);
        audited += 1;
        await context.onProgress(
          "WEBSITE_AUDIT",
          `Audited ${audited}/${candidates.length}: ${candidate.name} (${finding.verification}).`,
          30 + Math.round((audited / candidates.length) * 55),
        );
        return { candidate, finding };
      },
    );

    const pageVerified = auditedCandidates.filter(
      (entry) => entry.finding.website.verification === "PAGE_VERIFIED",
    );
    if (pageVerified.length < input.count) {
      const summaries = auditedCandidates
        .map(
          (entry) =>
            `${entry.candidate.name}: ${entry.finding.website.verification}${entry.finding.httpStatus ? ` (HTTP ${entry.finding.httpStatus})` : ""}`,
        )
        .join("; ");
      throw new ResearchExecutionError(
        "INSUFFICIENT_VERIFIED_PROSPECTS",
        `Only ${pageVerified.length} of ${input.count} required websites could be verified.`,
        `Candidates examined: ${candidates.length}. Outcomes — ${summaries}. No results were fabricated.`,
      );
    }

    await context.onProgress(
      "SCORING",
      "Scoring observed website opportunities from audit evidence…",
      90,
    );

    const selected = [...pageVerified]
      .sort((a, b) => b.finding.opportunity.score - a.finding.opportunity.score)
      .slice(0, input.count);

    const sources: SourceReference[] = [citySource];
    const prospects: Prospect[] = selected.map((entry, index) => {
      const { candidate, finding } = entry;
      const element = candidate.element;
      const tags = element.tags ?? {};
      const lat = element.lat ?? element.center?.lat;
      const lon = element.lon ?? element.center?.lon;
      if (lat === undefined || lon === undefined) {
        throw new ResearchExecutionError(
          "COORDINATES_MISSING",
          `The directory record for ${candidate.name} has no coordinates.`,
          `OSM ${element.type}/${element.id}`,
          false,
        );
      }
      const pid = prospectId(index);
      const osmSourceId = `${pid}-OSM`;
      const webSourceId = `${pid}-WEB`;
      const retrievedAt = finding.website.contentHash
        ? finding.researchTimestamp
        : executedAt;
      const osmSource: SourceReference = {
        id: osmSourceId,
        kind: "OPENSTREETMAP",
        title: `OpenStreetMap record: ${candidate.name}`,
        url: `https://www.openstreetmap.org/${element.type}/${element.id}`,
        publisher: "OpenStreetMap contributors (ODbL)",
        retrievedAt: executedAt,
        excerpt: `name=${candidate.name}; website=${
          candidate.websiteRaw ?? "not tagged"
        }; address=${addressFromTags(tags)}; city=${
          tags["addr:city"] ?? input.city
        }`,
      };
      const webSource: SourceReference = {
        id: webSourceId,
        kind: "WEBSITE",
        title: finding.website.title
          ? `Homepage: ${finding.website.title}`
          : `Homepage fetch: ${candidate.name}`,
        url: finding.website.finalUrl ?? candidate.websiteRaw ?? "",
        publisher: new URL(finding.website.finalUrl ?? candidate.websiteRaw!).hostname,
        retrievedAt,
        excerpt: excerptForWebsite(
          finding.website,
          finding.website.httpStatus,
          finding.website.audit?.serverHeader ?? null,
        ),
        contentHash: finding.website.contentHash ?? undefined,
      };
      sources.push(osmSource, webSource);

      const facts: ResearchFact[] = [];
      facts.push({
        statement: `OpenStreetMap lists “${candidate.name}” as a ${label}${
          addressFromTags(tags) === "Street address not tagged in OpenStreetMap"
            ? ""
            : ` at ${addressFromTags(tags)}`
        }, ${tags["addr:city"] ?? input.city}. Coordinates: ${lat.toFixed(6)}, ${lon.toFixed(6)}.`,
        sourceRefs: [osmSourceId],
      });
      if (finding.website.httpStatus !== null) {
        facts.push({
          statement: `The listed official website ${finding.website.finalUrl} returned HTTP ${finding.website.httpStatus} at ${retrievedAt}. Page title: ${
            finding.website.title ?? "(none)"
          }.`,
          sourceRefs: [webSourceId],
        });
      }
      if (finding.website.audit) {
        const audit = finding.website.audit;
        facts.push({
          statement: `Homepage audit observed: mobile viewport ${
            audit.viewport ? "present" : "absent"
          }; meta description ${
            audit.metaDescription ? "present" : "absent"
          }; online booking path ${
            audit.bookingLinks.length ? "present" : "absent"
          }; copyright year ${
            audit.copyrightYear ?? "not detected"
          }; business name match ${
            audit.titleMatch === "STRONG"
              ? "confirmed in title/heading"
              : audit.titleMatch === "PARTIAL"
                ? "partially confirmed in page text"
                : "not confirmed"
          }.`,
          sourceRefs: [webSourceId],
        });
      }

      const assumptions = [
        "Business identity and location rely on community-maintained OpenStreetMap data, not a company registry filing.",
        "Website ownership is inferred from the OpenStreetMap website tag; it was not independently confirmed with the owner.",
        "The need for a website refresh is inferred from observed technical signals. Owner intent and budget are unknown.",
        "The audit is a single homepage snapshot; JavaScript-rendered content and inner pages were not evaluated.",
        `${label.charAt(0).toUpperCase()}${label.slice(1)} has not been contacted. No message, publication, or spend occurred.`,
      ];
      if (finding.website.audit?.titleMatch === "NONE") {
        assumptions.push(
          "The audited website did not contain the business name in its title or main heading, so its ownership remains an assumption.",
        );
      }

      const website = finding.website;
      return {
        id: pid,
        rank: index + 1,
        businessName: candidate.name,
        category: label,
        location: {
          address: addressFromTags(tags),
          city: tags["addr:city"] ?? input.city,
          country: tags["addr:country"] ?? city.address?.country ?? "",
          lat,
          lon,
        },
        osm: {
          type: element.type,
          id: element.id,
          url: `https://www.openstreetmap.org/${element.type}/${element.id}`,
        },
        website,
        opportunity: finding.opportunity,
        facts,
        assumptions,
        sources: [osmSource, webSource],
        researchTimestamp: retrievedAt,
      };
    });

    const uniqueSources = [
      citySource,
      ...prospects.flatMap((prospect) => prospect.sources),
    ];

    await context.onProgress(
      "RESULT_ASSEMBLY",
      `Prepared ${prospects.length} evidence-backed prospect records.`,
      95,
    );

    return {
      assignment: {
        city: city.display_name,
        category: label,
        requestedCount: input.count,
        deliveredCount: prospects.length,
      },
      prospects,
      methodology: [
        "Resolved the requested city through the public Nominatim geocoder.",
        "Queried the public Overpass API for OpenStreetMap businesses carrying a website tag inside the city bounding box.",
        "Deduplicated businesses by name and website domain.",
        "Fetched each candidate homepage over HTTP(S) with a capped response size and a private-address guard.",
        "Extracted observable technical signals from homepage HTML and response headers.",
        "Required a successful page fetch before marking an official website as PAGE_VERIFIED.",
        "Ranked prospects only by observed technical opportunity signals; no outreach or spending occurred.",
      ],
      limitations: [
        "OpenStreetMap is community-maintained; listings can be incomplete or out of date.",
        "Only the homepage was audited, once, without JavaScript execution.",
        "Technical findings do not prove commercial need, authority to buy, or budget.",
        "No phone, email, or social outreach was attempted or sent.",
        "No paid search, enrichment, or AI model service was used.",
      ],
      sources: uniqueSources,
      executedAt,
      provider: this.name,
      candidatesExamined: candidates.length,
      websitesAudited: audited,
    };
  }

  private async auditWebsite(
    candidate: Candidate,
  ): Promise<{
    website: WebsiteFinding;
    opportunity: ReturnType<typeof buildOpportunity>;
    researchTimestamp: string;
  }> {
    const osmRef = "OSM";
    const webRef = "WEB";
    if (!candidate.websiteRaw || candidate.socialOnly) {
      const website: WebsiteFinding = {
        url: candidate.websiteRaw,
        domain: candidate.websiteRaw
          ? new URL(candidate.websiteRaw).hostname
          : null,
        verification: "NOT_PROVIDED",
        httpStatus: null,
        finalUrl: null,
        https: candidate.websiteRaw?.startsWith("https://") ?? false,
        title: null,
        description: null,
        responseMs: null,
        contentHash: null,
        audit: null,
        notes: [
          candidate.socialOnly
            ? "The directory only lists a social-media profile, not an official website."
            : "No official website was recorded in the directory.",
        ],
      };
      return {
        website,
        opportunity: buildOpportunity(website, null, {
          website: webRef,
          osm: osmRef,
        }),
        researchTimestamp: new Date().toISOString(),
      };
    }

    try {
      const response = await safeFetch(candidate.websiteRaw);
      const audit = new Date().toISOString();
      const contentType = response.headers.get("content-type");
      const serverHeader = response.headers.get("server");
      const finalUrl = response.finalUrl;
      const htmlLike =
        !contentType ||
        /text\/html|application\/xhtml\+xml/i.test(contentType);
      const ok = response.status >= 200 && response.status < 300;
      if (!ok || !htmlLike) {
        const website: WebsiteFinding = {
          url: candidate.websiteRaw,
          domain: new URL(finalUrl).hostname,
          verification: !ok ? "UNREACHABLE" : "TAG_ONLY",
          httpStatus: response.status,
          finalUrl,
          https: finalUrl.startsWith("https://"),
          title: null,
          description: null,
          responseMs: Math.round(response.responseMs),
          contentHash: response.bodyText
            ? createHash("sha256").update(response.bodyText).digest("hex")
            : null,
          audit: null,
          notes: [
            !ok
              ? `The official website returned HTTP ${response.status}.`
              : `The URL returned non-HTML content (${contentType}).`,
          ],
        };
        return {
          website,
          opportunity: buildOpportunity(website, response.responseMs, {
            website: webRef,
            osm: osmRef,
          }),
          researchTimestamp: audit,
        };
      }
      const contentHash = createHash("sha256")
        .update(response.bodyText)
        .digest("hex");
      const parsed = auditHtml(
        response.bodyText,
        candidate.name,
        contentType,
        serverHeader,
        response.bytes,
      );
      const title = (response.bodyText.match(/<title[^>]*>([\s\S]*?)<\/title>/i) ?? [])[1];
      const website: WebsiteFinding = {
        url: candidate.websiteRaw,
        domain: new URL(finalUrl).hostname,
        verification: "PAGE_VERIFIED",
        httpStatus: response.status,
        finalUrl,
        https: finalUrl.startsWith("https://"),
        title: title
          ? title.replace(/<[^>]+>/g, "").replace(/\s+/g, " ").trim() || null
          : null,
        description: parsed.metaDescription,
        responseMs: Math.round(response.responseMs),
        contentHash,
        audit: parsed,
        notes: response.truncated
          ? ["The homepage exceeded the 1.5 MB audit cap; analysis used the first 1.5 MB."]
          : [],
      };
      return {
        website,
        opportunity: buildOpportunity(website, response.responseMs, {
          website: webRef,
          osm: osmRef,
        }),
        researchTimestamp: audit,
      };
    } catch (error) {
      const website: WebsiteFinding = {
        url: candidate.websiteRaw,
        domain: new URL(candidate.websiteRaw).hostname,
        verification: "UNREACHABLE",
        httpStatus: null,
        finalUrl: null,
        https: candidate.websiteRaw.startsWith("https://"),
        title: null,
        description: null,
        responseMs: null,
        contentHash: null,
        audit: null,
        notes: [
          `The official website could not be fetched: ${
            error instanceof Error ? error.message : String(error)
          }`,
        ],
      };
      return {
        website,
        opportunity: buildOpportunity(website, null, {
          website: webRef,
          osm: osmRef,
        }),
        researchTimestamp: new Date().toISOString(),
      };
    }
  }
}

import type { Response } from "express";
import type { Task } from "../shared/types.ts";

/**
 * Server-sent-events fan-out. Sends the full task on every mutation so clients
 * never have to infer whether an update is real.
 */
export class HqBus {
  private clients = new Set<Response>();

  subscribe(res: Response): () => void {
    this.clients.add(res);
    return () => this.clients.delete(res);
  }

  get clientCount(): number {
    return this.clients.size;
  }

  broadcastTask(task: Task): number {
    const payload = `event: task\ndata: ${JSON.stringify(task)}\n\n`;
    let delivered = 0;
    for (const client of this.clients) {
      try {
        client.write(payload);
        delivered += 1;
      } catch {
        this.clients.delete(client);
      }
    }
    return delivered;
  }

  broadcastSystem(data: unknown): void {
    const payload = `event: system\ndata: ${JSON.stringify(data)}\n\n`;
    for (const client of this.clients) {
      try {
        client.write(payload);
      } catch {
        this.clients.delete(client);
      }
    }
  }

  closeAll(): void {
    for (const client of this.clients) {
      try {
        client.end();
      } catch {
        // ignore
      }
    }
    this.clients.clear();
  }
}

import type {
  OutreachDraftResult,
  Prospect,
  ResearchInput,
  ResearchResult,
  Task,
  TaskStatus,
} from "../shared/types.ts";
import { eventId, nowIso, taskId } from "./ids.ts";
import type { HqBus } from "./bus.ts";
import type { TaskStore } from "./store.ts";
import {
  ResearchExecutionError,
  type ResearchProvider,
} from "./research/liveResearch.ts";

export interface RunnerOptions {
  store: TaskStore;
  provider: ResearchProvider;
  bus: HqBus;
  mode: "LIVE" | "TEST";
}

export class HqRunner {
  private queue: string[] = [];
  private draining = false;
  private stopped = false;

  constructor(private readonly options: RunnerOptions) {}

  async submitResearch(input: ResearchInput): Promise<Task> {
    const timestamp = nowIso();
    const task: Task = {
      id: taskId(),
      type: "PROSPECT_RESEARCH",
      title: `Prospect research — ${input.count} ${input.category}s in ${input.city}`,
      brief: `Find and verify ${input.count} ${input.category} prospects in ${input.city}. Capture official-site evidence, observable online-presence gaps, sources, and timestamps. No outreach.`,
      input,
      status: "QUEUED",
      createdAt: timestamp,
      updatedAt: timestamp,
      startedAt: null,
      completedAt: null,
      progress: {
        stage: "QUEUED",
        message: "Waiting for NOVA's execution worker.",
        percent: 0,
      },
      events: [
        {
          id: eventId(),
          at: timestamp,
          kind: "STATUS",
          message: "Task accepted into the durable queue.",
          status: "QUEUED",
        },
      ],
      execution: {
        provider: this.options.provider.name,
        mode: this.options.mode,
        attemptedPasses: 0,
      },
      result: null,
      error: null,
      approval: null,
      delivery: {
        persisted: false,
        persistedAt: null,
        readbackVerified: false,
        verifiedAt: null,
        broadcastClients: 0,
        apiPath: "/api/tasks/",
      },
    };
    await this.options.store.upsert(task);
    this.options.bus.broadcastTask(task);
    this.queue.push(task.id);
    queueMicrotask(() => void this.drain());
    return structuredClone(task);
  }

  async submitOutreach(parentTaskId: string, prospectId: string): Promise<Task> {
    const parent = this.options.store.get(parentTaskId);
    if (!parent) {
      throw new RunnerError("PARENT_NOT_FOUND", "The research task was not found.", 404);
    }
    if (parent.status !== "COMPLETED" || !parent.result) {
      throw new RunnerError(
        "PARENT_NOT_COMPLETED",
        "Outreach can only be drafted from a COMPLETED research task.",
        409,
      );
    }
    const research = parent.result as ResearchResult;
    const prospect = research.prospects?.find((item) => item.id === prospectId);
    if (!prospect) {
      throw new RunnerError(
        "PROSPECT_NOT_FOUND",
        "That prospect does not belong to the parent research task.",
        404,
      );
    }

    const timestamp = nowIso();
    const draft = buildDraft(prospect);
    const result: OutreachDraftResult = {
      prospectId: prospect.id,
      businessName: prospect.businessName,
      draft,
      approval: {
        status: "PENDING",
        requestedAt: timestamp,
        decidedAt: null,
        note: null,
      },
      sent: false,
      note: "This is a local draft only. AGENT HQ has no outbound-message capability and nothing was sent.",
    };
    const task: Task = {
      id: taskId(),
      type: "OUTREACH_DRAFT",
      title: `Outreach draft — ${prospect.businessName}`,
      brief:
        "Prepare a local outreach draft from verified research. Requires operator approval; no send bridge exists.",
      input: { prospectId, parentTaskId },
      status: "AWAITING_APPROVAL",
      createdAt: timestamp,
      updatedAt: timestamp,
      startedAt: timestamp,
      completedAt: null,
      progress: {
        stage: "APPROVAL_GATE",
        message: "Draft prepared locally. Awaiting operator decision.",
        percent: 100,
      },
      events: [
        {
          id: eventId(),
          at: timestamp,
          kind: "STATUS",
          message:
            "Draft prepared from stored evidence. Awaiting approval; no message sent.",
          status: "AWAITING_APPROVAL",
        },
      ],
      execution: {
        provider: "manual-approval-gate",
        mode: this.options.mode,
        attemptedPasses: 0,
      },
      result,
      error: null,
      approval: {
        status: "PENDING",
        requestedAt: timestamp,
        decidedAt: null,
        note: null,
        scope:
          "Approval authorises manual use of this draft. AGENT HQ cannot send email or publish anything.",
      },
      delivery: {
        persisted: false,
        persistedAt: null,
        readbackVerified: false,
        verifiedAt: null,
        broadcastClients: 0,
        apiPath: "/api/tasks/",
      },
    };
    task.delivery.apiPath = `/api/tasks/${task.id}`;
    await this.options.store.upsert(task);
    const readback = await this.options.store.readFromDisk(task.id);
    task.delivery = {
      persisted: Boolean(readback?.result),
      persistedAt: timestamp,
      readbackVerified: Boolean(readback?.result),
      verifiedAt: nowIso(),
      broadcastClients: this.options.bus.broadcastTask(task),
      apiPath: `/api/tasks/${task.id}`,
    };
    await this.options.store.upsert(task);
    this.options.bus.broadcastTask(task);
    return structuredClone(task);
  }

  async retry(id: string): Promise<Task> {
    const task = this.options.store.get(id);
    if (!task) throw new RunnerError("TASK_NOT_FOUND", "Task not found.", 404);
    if (task.status !== "FAILED") {
      throw new RunnerError(
        "TASK_NOT_RETRYABLE",
        "Only FAILED tasks can be retried.",
        409,
        `Current status: ${task.status}.`,
      );
    }
    if (task.error && !task.error.retryable) {
      throw new RunnerError(
        "TASK_NOT_RETRYABLE",
        "This failure is marked non-retryable.",
        409,
        task.error.detail,
      );
    }
    if (task.type !== "PROSPECT_RESEARCH") {
      throw new RunnerError(
        "TASK_NOT_RETRYABLE",
        "Only research tasks have an automatic retry path.",
        409,
      );
    }
    const timestamp = nowIso();
    task.status = "QUEUED";
    task.updatedAt = timestamp;
    task.startedAt = null;
    task.completedAt = null;
    task.error = null;
    task.result = null;
    task.progress = {
      stage: "QUEUED",
      message: "Retry accepted. Waiting for the execution worker.",
      percent: 0,
    };
    task.delivery = {
      persisted: false,
      persistedAt: null,
      readbackVerified: false,
      verifiedAt: null,
      broadcastClients: 0,
      apiPath: `/api/tasks/${task.id}`,
    };
    task.events.push({
      id: eventId(),
      at: timestamp,
      kind: "STATUS",
      message: "Retry accepted by operator. Re-queued for execution.",
      status: "QUEUED",
    });
    await this.options.store.upsert(task);
    this.options.bus.broadcastTask(task);
    this.queue.push(task.id);
    queueMicrotask(() => void this.drain());
    return structuredClone(task);
  }

  async decide(
    id: string,
    decision: "APPROVE" | "REJECT",
    note?: string,
  ): Promise<Task> {
    const task = this.options.store.get(id);
    if (!task) throw new RunnerError("TASK_NOT_FOUND", "Task not found.", 404);
    if (task.status !== "AWAITING_APPROVAL") {
      throw new RunnerError(
        "NO_PENDING_APPROVAL",
        "This task has no pending approval.",
        409,
        `Current status: ${task.status}.`,
      );
    }
    const timestamp = nowIso();
    const approved = decision === "APPROVE";
    if (task.approval) {
      task.approval.status = approved ? "APPROVED" : "REJECTED";
      task.approval.decidedAt = timestamp;
      task.approval.note = note?.trim() || null;
    }
    const result = task.result as OutreachDraftResult | null;
    if (result && "approval" in result) {
      result.approval.status = approved ? "APPROVED" : "REJECTED";
      result.approval.decidedAt = timestamp;
      result.approval.note = note?.trim() || null;
    }
    task.updatedAt = timestamp;
    if (approved) {
      task.status = "COMPLETED";
      task.completedAt = timestamp;
      task.progress = {
        stage: "APPROVED",
        message:
          "Draft approved for manual use. No message was sent by AGENT HQ.",
        percent: 100,
      };
      task.events.push({
        id: eventId(),
        at: timestamp,
        kind: "STATUS",
        message:
          "Operator approved the local draft. Execution bridge has no send capability; nothing was sent.",
        status: "COMPLETED",
      });
    } else {
      task.status = "FAILED";
      task.error = {
        code: "REJECTED_BY_OPERATOR",
        message: "The operator rejected this draft.",
        detail: note?.trim() || null,
        at: timestamp,
        retryable: false,
      };
      task.progress = {
        stage: "REJECTED",
        message: "Draft rejected. No message was sent.",
        percent: 100,
      };
      task.events.push({
        id: eventId(),
        at: timestamp,
        kind: "ERROR",
        message: "Operator rejected the draft. No message was sent.",
        status: "FAILED",
      });
    }
    await this.options.store.upsert(task);
    this.options.bus.broadcastTask(task);
    return structuredClone(task);
  }

  get queueDepth(): number {
    return this.queue.length;
  }

  async stop(): Promise<void> {
    this.stopped = true;
  }

  private async drain(): Promise<void> {
    if (this.draining || this.stopped) return;
    this.draining = true;
    try {
      while (this.queue.length > 0) {
        const id = this.queue.shift();
        if (!id) continue;
        const task = this.options.store.get(id);
        if (!task || task.status !== "QUEUED") continue;
        await this.executeResearch(task);
      }
    } finally {
      this.draining = false;
    }
  }

  private async executeResearch(task: Task): Promise<void> {
    const startedAt = nowIso();
    task.status = "RUNNING";
    task.startedAt = startedAt;
    task.updatedAt = startedAt;
    task.execution.attemptedPasses += 1;
    task.progress = {
      stage: "STARTING",
      message: "NOVA acquired the task. Opening live data sources…",
      percent: 2,
    };
    task.events.push({
      id: eventId(),
      at: startedAt,
      kind: "STATUS",
      message: "Execution started by the live research bridge.",
      status: "RUNNING",
    });
    await this.options.store.upsert(task);
    this.options.bus.broadcastTask(task);

    try {
      const input = task.input as ResearchInput;
      const result = await this.options.provider.execute(input, {
        onProgress: async (stage, message, percent) => {
          const timestamp = nowIso();
          task.progress = { stage, message, percent };
          task.updatedAt = timestamp;
          task.events.push({
            id: eventId(),
            at: timestamp,
            kind: "PROGRESS",
            message,
          });
          await this.options.store.upsert(task);
          this.options.bus.broadcastTask(task);
        },
      });

      if (
        !result.prospects ||
        result.prospects.length !== input.count ||
        result.prospects.some((prospect) => !prospect.sources.length)
      ) {
        throw new ResearchExecutionError(
          "RESULT_INCOMPLETE",
          "The research result did not contain the required evidence-backed prospects.",
          `Expected ${input.count}; received ${result.prospects?.length ?? 0}.`,
          true,
        );
      }

      const persistedAt = nowIso();
      task.result = result;
      task.updatedAt = persistedAt;
      task.progress = {
        stage: "DELIVERY_CHECK",
        message: "Verifying results are durably stored and readable…",
        percent: 97,
      };
      task.delivery = {
        persisted: false,
        persistedAt,
        readbackVerified: false,
        verifiedAt: null,
        broadcastClients: 0,
        apiPath: `/api/tasks/${task.id}`,
      };
      await this.options.store.upsert(task);

      const readback = await this.options.store.readFromDisk(task.id);
      const readbackResult = readback?.result as ResearchResult | null;
      const verified =
        Boolean(readbackResult?.prospects) &&
        readbackResult?.prospects.length === input.count &&
        readbackResult.prospects.every(
          (prospect) =>
            prospect.businessName.length > 0 && prospect.sources.length > 0,
        );
      if (!verified) {
        throw new ResearchExecutionError(
          "DELIVERY_UNVERIFIED",
          "Stored results failed the read-back verification.",
          "The task was not marked COMPLETED. Re-run to regenerate the result.",
          true,
        );
      }

      const verifiedAt = nowIso();
      task.delivery = {
        persisted: true,
        persistedAt,
        readbackVerified: true,
        verifiedAt,
        broadcastClients: this.options.bus.broadcastTask(task),
        apiPath: `/api/tasks/${task.id}`,
      };
      task.events.push({
        id: eventId(),
        at: verifiedAt,
        kind: "DELIVERY",
        message: `Results persisted and read back successfully. Broadcast to ${task.delivery.broadcastClients} connected interface client(s).`,
      });
      task.status = "COMPLETED";
      task.completedAt = verifiedAt;
      task.updatedAt = verifiedAt;
      task.progress = {
        stage: "COMPLETED",
        message: `${result.prospects.length} verified prospects delivered with sources.`,
        percent: 100,
      };
      task.events.push({
        id: eventId(),
        at: verifiedAt,
        kind: "STATUS",
        message:
          "Task COMPLETED only after durable result read-back and interface delivery attempt.",
        status: "COMPLETED",
      });
      await this.options.store.upsert(task);
      this.options.bus.broadcastTask(task);
    } catch (error) {
      const timestamp = nowIso();
      const known =
        error instanceof ResearchExecutionError
          ? error
          : new ResearchExecutionError(
              "INTERNAL_ERROR",
              "The research bridge failed unexpectedly.",
              error instanceof Error ? error.message : String(error),
              true,
            );
      task.status = "FAILED";
      task.updatedAt = timestamp;
      task.completedAt = null;
      task.error = {
        code: known.code,
        message: known.message,
        detail: known.detail,
        at: timestamp,
        retryable: known.retryable,
      };
      task.progress = {
        stage: "FAILED",
        message: known.message,
        percent: 100,
      };
      task.events.push({
        id: eventId(),
        at: timestamp,
        kind: "ERROR",
        message: `${known.code}: ${known.message}`,
        status: "FAILED",
      });
      // A failed run must not retain results from an earlier pass.
      task.result = null;
      task.delivery = {
        persisted: false,
        persistedAt: null,
        readbackVerified: false,
        verifiedAt: null,
        broadcastClients: 0,
        apiPath: `/api/tasks/${task.id}`,
      };
      await this.options.store.upsert(task);
      this.options.bus.broadcastTask(task);
    }
  }
}

export class RunnerError extends Error {
  constructor(
    readonly code: string,
    message: string,
    readonly status: number,
    readonly detail: string | null = null,
  ) {
    super(message);
    this.name = "RunnerError";
  }
}

function buildDraft(prospect: Prospect): OutreachDraftResult["draft"] {
  const topSignals = prospect.opportunity.signals
    .slice(0, 2)
    .map((signal) => signal.label);
  const observations = topSignals.length
    ? topSignals.map((label) => `- ${label}`).join("\n")
    : "- No material technical gap was observed.";
  const body = `Hello ${prospect.businessName} team,

I am writing from DEEMANNIE'S DIGITAL. While reviewing publicly available information about ${prospect.businessName} in ${prospect.location.city}, I recorded the following observations on your public website:

${observations}

Evidence reviewed: ${prospect.website.finalUrl ?? prospect.website.url ?? "no official website found"}

These are technical observations, not assumptions about your plans. If useful, I can share a short audit with the supporting evidence. If this is not relevant, no reply is needed.

This draft was prepared by AGENT HQ and requires human approval. Nothing has been sent.

DEEMANNIE'S DIGITAL`;

  return {
    subject: `A website observation for ${prospect.businessName}`,
    body,
    channel: "email",
  };
}

export function countStatuses(tasks: Task[]): Record<TaskStatus, number> {
  const counts: Record<TaskStatus, number> = {
    QUEUED: 0,
    RUNNING: 0,
    COMPLETED: 0,
    FAILED: 0,
    AWAITING_APPROVAL: 0,
  };
  for (const task of tasks) counts[task.status] += 1;
  return counts;
}

import fs from "node:fs";
import path from "node:path";
import express, { type NextFunction, type Request, type Response } from "express";
import { z } from "zod";
import type { SystemStatus, TaskStatus } from "../shared/types.ts";
import type { HqBus } from "./bus.ts";
import { HqRunner, RunnerError, countStatuses } from "./runner.ts";
import type { TaskStore } from "./store.ts";

export interface AppOptions {
  store: TaskStore;
  runner: HqRunner;
  bus: HqBus;
  version: string;
  startedAt: string;
  researchProvider: string;
  enableRateLimit?: boolean;
  staticDir?: string | null;
}

const researchSchema = z.object({
  city: z
    .string()
    .trim()
    .min(2)
    .max(80)
    .refine((value) => !/[\u0000-\u001f]/.test(value), "City contains control characters"),
  category: z.enum(["cafe", "restaurant", "bakery"]),
  count: z.number().int().min(1).max(5).default(3),
});

const outreachSchema = z.object({
  parentTaskId: z.string().trim().min(3).max(40),
  prospectId: z.string().trim().min(3).max(80),
});

const decisionSchema = z.object({
  decision: z.enum(["APPROVE", "REJECT"]),
  note: z.string().trim().max(500).optional(),
});

type AsyncHandler = (
  req: Request,
  res: Response,
  next: NextFunction,
) => Promise<void>;

function asyncHandler(handler: AsyncHandler) {
  return (req: Request, res: Response, next: NextFunction) => {
    void handler(req, res, next).catch(next);
  };
}

function errorBody(code: string, message: string, detail?: string | null) {
  return { error: { code, message, detail: detail ?? null } };
}

export function createApp(options: AppOptions) {
  const app = express();
  app.disable("x-powered-by");
  app.use(express.json({ limit: "32kb" }));

  app.use((_req, res, next) => {
    res.setHeader("X-Content-Type-Options", "nosniff");
    res.setHeader("Referrer-Policy", "no-referrer");
    res.setHeader("X-Frame-Options", "DENY");
    res.setHeader(
      "Permissions-Policy",
      "camera=(), microphone=(), geolocation=()",
    );
    res.setHeader(
      "Content-Security-Policy",
      "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self'; connect-src 'self'; font-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'",
    );
    next();
  });

  const attempts = new Map<string, number[]>();
  const rateLimit =
    options.enableRateLimit === false
      ? (_req: Request, _res: Response, next: NextFunction) => next()
      : (req: Request, res: Response, next: NextFunction) => {
          if (req.method !== "POST") return next();
          const key = req.ip ?? "unknown";
          const now = Date.now();
          const recent = (attempts.get(key) ?? []).filter(
            (stamp) => now - stamp < 60_000,
          );
          if (recent.length >= 8) {
            res
              .status(429)
              .json(
                errorBody(
                  "RATE_LIMITED",
                  "Too many submissions. Wait a minute and retry.",
                ),
              );
            return;
          }
          recent.push(now);
          attempts.set(key, recent);
          next();
        };
  app.use(rateLimit);

  app.get("/api/health", (_req, res) => {
    res.json({
      status: "ok",
      uptimeSeconds: Math.round(process.uptime()),
      version: options.version,
    });
  });

  app.get("/api/system", (_req, res) => {
    const tasks = options.store.list();
    const system: SystemStatus = {
      mode: "LIVE",
      version: options.version,
      startedAt: options.startedAt,
      researchProvider: options.researchProvider,
      approvalPolicy:
        "Outreach drafts require operator approval. No send, publish, or payment bridge is configured.",
      connectedClients: options.bus.clientCount,
      taskCounts: countStatuses(tasks),
      capabilities: [
        {
          id: "live-research",
          label: "Open-data prospect research",
          status: "LIVE",
          detail: options.researchProvider,
        },
        {
          id: "website-audit",
          label: "Public homepage audit",
          status: "LIVE",
          detail: "HTTP fetch, capped HTML analysis, evidence hashes",
        },
        {
          id: "outreach-draft",
          label: "Outreach drafts",
          status: "LIVE",
          detail: "Local drafts only; approval gate enforced",
        },
        {
          id: "email-send",
          label: "Email delivery",
          status: "BLOCKED",
          detail: "No email provider or credentials configured",
        },
        {
          id: "website-publish",
          label: "Website publishing",
          status: "BLOCKED",
          detail: "No deployment target or approval workflow configured",
        },
        {
          id: "payments",
          label: "Payments and spend",
          status: "BLOCKED",
          detail: "No payment service configured",
        },
      ],
    };
    res.json(system);
  });

  app.get("/api/tasks", (_req, res) => {
    res.json({ tasks: options.store.list() });
  });

  app.get("/api/tasks/:id", (req, res) => {
    const task = options.store.get(req.params.id);
    if (!task) {
      res
        .status(404)
        .json(errorBody("TASK_NOT_FOUND", "No task exists with that id."));
      return;
    }
    res.json({ task });
  });

  app.post(
    "/api/tasks/research",
    asyncHandler(async (req, res) => {
      const parsed = researchSchema.safeParse(req.body);
      if (!parsed.success) {
        res.status(400).json(
          errorBody(
            "INVALID_INPUT",
            "The research assignment is invalid.",
            parsed.error.issues
              .map((issue) => `${issue.path.join(".")}: ${issue.message}`)
              .join("; "),
          ),
        );
        return;
      }
      const task = await options.runner.submitResearch(parsed.data);
      res.status(202).json({ task });
    }),
  );

  app.post(
    "/api/tasks/outreach",
    asyncHandler(async (req, res) => {
      const parsed = outreachSchema.safeParse(req.body);
      if (!parsed.success) {
        res.status(400).json(
          errorBody(
            "INVALID_INPUT",
            "The outreach request is invalid.",
            parsed.error.issues
              .map((issue) => `${issue.path.join(".")}: ${issue.message}`)
              .join("; "),
          ),
        );
        return;
      }
      const task = await options.runner.submitOutreach(
        parsed.data.parentTaskId,
        parsed.data.prospectId,
      );
      res.status(201).json({ task });
    }),
  );

  app.post(
    "/api/tasks/:id/retry",
    asyncHandler(async (req, res) => {
      const task = await options.runner.retry(req.params.id);
      res.status(202).json({ task });
    }),
  );

  app.post(
    "/api/tasks/:id/decision",
    asyncHandler(async (req, res) => {
      const parsed = decisionSchema.safeParse(req.body);
      if (!parsed.success) {
        res.status(400).json(
          errorBody(
            "INVALID_INPUT",
            "Decision is invalid.",
            parsed.error.issues.map((issue) => issue.message).join("; "),
          ),
        );
        return;
      }
      const task = await options.runner.decide(
        req.params.id,
        parsed.data.decision,
        parsed.data.note,
      );
      res.json({ task });
    }),
  );

  app.get("/api/events", (req, res) => {
    res.setHeader("Content-Type", "text/event-stream");
    res.setHeader("Cache-Control", "no-cache, no-transform");
    res.setHeader("Connection", "keep-alive");
    res.setHeader("X-Accel-Buffering", "no");
    res.flushHeaders();

    const send = (event: string, data: unknown) => {
      res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
    };
    send("snapshot", {
      tasks: options.store.list(),
      connectedClients: options.bus.clientCount + 1,
      at: new Date().toISOString(),
    });
    const unsubscribe = options.bus.subscribe(res);
    const heartbeat = setInterval(() => {
      res.write(`: heartbeat ${Date.now()}\n\n`);
    }, 15_000);
    req.on("close", () => {
      clearInterval(heartbeat);
      unsubscribe();
    });
  });

  app.use("/api", (_req, res) => {
    res.status(404).json(errorBody("NOT_FOUND", "Unknown API route."));
  });

  if (options.staticDir && fs.existsSync(options.staticDir)) {
    app.use(express.static(options.staticDir, { index: false }));
    app.get("*", (_req, res) => {
      res.sendFile(path.join(options.staticDir!, "index.html"));
    });
  }

  app.use(
    (error: unknown, _req: Request, res: Response, _next: NextFunction) => {
      if (error instanceof RunnerError) {
        res
          .status(error.status)
          .json(errorBody(error.code, error.message, error.detail));
        return;
      }
      if (error instanceof SyntaxError && "body" in error) {
        res
          .status(400)
          .json(errorBody("INVALID_JSON", "Request body must be valid JSON."));
        return;
      }
      console.error("[hq] unhandled request error:", error);
      res
        .status(500)
        .json(
          errorBody(
            "INTERNAL_ERROR",
            "AGENT HQ hit an unexpected server error.",
            error instanceof Error ? error.message : String(error),
          ),
        );
    },
  );

  return app;
}

export function emptyCounts(): Record<TaskStatus, number> {
  return {
    QUEUED: 0,
    RUNNING: 0,
    COMPLETED: 0,
    FAILED: 0,
    AWAITING_APPROVAL: 0,
  };
}

