import path from "node:path";
import { createApp } from "./app.ts";
import { HqBus } from "./bus.ts";
import { LiveResearchProvider } from "./research/liveResearch.ts";
import { HqRunner } from "./runner.ts";
import { TaskStore } from "./store.ts";

const PORT = Number(process.env.PORT ?? 3002);
const DATA_DIR = process.env.HQ_DATA_DIR ?? path.resolve(process.cwd(), "data");
const VERSION = "2.0.0";
const startedAt = new Date().toISOString();

const store = new TaskStore(path.join(DATA_DIR, "hq.json"));
await store.init();

const bus = new HqBus();
const provider = new LiveResearchProvider();
const runner = new HqRunner({
  store,
  provider,
  bus,
  mode: process.env.HQ_MODE === "TEST" ? "TEST" : "LIVE",
});

await runner.recover();

const app = createApp({
  store,
  runner,
  bus,
  version: VERSION,
  startedAt,
  researchProvider: provider.name,
  staticDir: path.resolve(process.cwd(), "dist"),
});

const server = app.listen(PORT, () => {
  console.log(`[hq] AGENT HQ listening on http://localhost:${PORT}`);
  console.log(`[hq] mode=${runner.queueDepth >= 0 ? "LIVE" : "LIVE"} data=${DATA_DIR}`);
  console.log(`[hq] research provider: ${provider.name}`);
  console.log("[hq] outbound messaging, publishing and payments: BLOCKED");
});

function shutdown(signal: string) {
  console.log(`[hq] ${signal} received; shutting down`);
  bus.closeAll();
  server.close(() => {
    void runner.stop().then(() => process.exit(0));
  });
  setTimeout(() => process.exit(1), 5_000).unref();
}

process.on("SIGINT", () => shutdown("SIGINT"));
process.on("SIGTERM", () => shutdown("SIGTERM"));

import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App.tsx";
import "./styles.css";

ReactDOM.createRoot(document.getElementById("root")!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

import type {
  ApiError,
  CreateResearchRequest,
  DecisionRequest,
  SystemStatus,
  Task,
} from "./types.ts";

async function request<T>(
  path: string,
  init?: RequestInit,
): Promise<T> {
  const response = await fetch(path, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const body = (await response.json().catch(() => null)) as
    | T
    | ApiError
    | null;
  if (!response.ok) {
    const error = body as ApiError | null;
    throw new Error(
      error?.error?.message
        ? `${error.error.message}${error.error.detail ? ` ${error.error.detail}` : ""}`
        : `Request failed with HTTP ${response.status}`,
    );
  }
  return body as T;
}

export async function fetchTasks(): Promise<Task[]> {
  const data = await request<{ tasks: Task[] }>("/api/tasks");
  return data.tasks;
}

export async function fetchSystem(): Promise<SystemStatus> {
  return request<SystemStatus>("/api/system");
}

export async function submitResearch(
  input: CreateResearchRequest,
): Promise<Task> {
  const data = await request<{ task: Task }>("/api/tasks/research", {
    method: "POST",
    body: JSON.stringify(input),
  });
  return data.task;
}

export async function submitOutreach(
  parentTaskId: string,
  prospectId: string,
): Promise<Task> {
  const data = await request<{ task: Task }>("/api/tasks/outreach", {
    method: "POST",
    body: JSON.stringify({ parentTaskId, prospectId }),
  });
  return data.task;
}

export async function retryTask(id: string): Promise<Task> {
  const data = await request<{ task: Task }>(`/api/tasks/${id}/retry`, {
    method: "POST",
    body: JSON.stringify({}),
  });
  return data.task;
}

export async function decideTask(
  id: string,
  decision: DecisionRequest,
): Promise<Task> {
  const data = await request<{ task: Task }>(`/api/tasks/${id}/decision`, {
    method: "POST",
    body: JSON.stringify(decision),
  });
  return data.task;
}

import type { ReactNode } from "react";
import {
  AlertTriangle,
  Check,
  CheckCircle2,
  Clock3,
  Loader2,
  ShieldAlert,
  XCircle,
} from "lucide-react";
import type { TaskStatus } from "../types.ts";

export const STATUS_META: Record<
  TaskStatus,
  { label: string; className: string; icon: ReactNode }
> = {
  QUEUED: {
    label: "QUEUED",
    className: "status-queued",
    icon: <Clock3 size={13} aria-hidden="true" />,
  },
  RUNNING: {
    label: "RUNNING",
    className: "status-running",
    icon: <Loader2 size={13} className="spin" aria-hidden="true" />,
  },
  COMPLETED: {
    label: "COMPLETED",
    className: "status-completed",
    icon: <CheckCircle2 size={13} aria-hidden="true" />,
  },
  FAILED: {
    label: "FAILED",
    className: "status-failed",
    icon: <XCircle size={13} aria-hidden="true" />,
  },
  AWAITING_APPROVAL: {
    label: "AWAITING APPROVAL",
    className: "status-approval",
    icon: <ShieldAlert size={13} aria-hidden="true" />,
  },
};

export function StatusBadge({ status }: { status: TaskStatus }) {
  const meta = STATUS_META[status];
  return (
    <span className={`status-badge ${meta.className}`}>
      {meta.icon}
      {meta.label}
    </span>
  );
}

export function formatTimestamp(iso: string | null | undefined): string {
  if (!iso) return "—";
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return "—";
  return `${new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
    timeZone: "UTC",
  }).format(date)} UTC`;
}

export function formatDate(iso: string | null | undefined): string {
  if (!iso) return "—";
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  }).format(date);
}

export function shortId(id: string): string {
  return id.length > 12 ? id.slice(0, 12) : id;
}

export function Panel({
  title,
  eyebrow,
  action,
  children,
  className = "",
}: {
  title: string;
  eyebrow?: string;
  action?: ReactNode;
  children: ReactNode;
  className?: string;
}) {
  return (
    <section className={`panel ${className}`}>
      <header className="panel-head">
        <div>
          {eyebrow ? <p className="eyebrow">{eyebrow}</p> : null}
          <h2>{title}</h2>
        </div>
        {action}
      </header>
      {children}
    </section>
  );
}

export function SourceChip({
  id,
  label,
  title,
}: {
  id: string;
  label: string;
  title?: string;
}) {
  return (
    <span className="source-chip" title={title ?? id}>
      <span className="source-chip-id">{label}</span>
    </span>
  );
}

export function VerificationBadge({
  verification,
}: {
  verification:
    | "PAGE_VERIFIED"
    | "TAG_ONLY"
    | "UNREACHABLE"
    | "NOT_PROVIDED";
}) {
  const config = {
    PAGE_VERIFIED: { label: "PAGE VERIFIED", className: "verify-good" },
    TAG_ONLY: { label: "TAG ONLY", className: "verify-warn" },
    UNREACHABLE: { label: "UNREACHABLE", className: "verify-bad" },
    NOT_PROVIDED: { label: "NOT PROVIDED", className: "verify-bad" },
  }[verification];
  return <span className={`verify-badge ${config.className}`}>{config.label}</span>;
}

export function CheckLine({
  ok,
  label,
  detail,
}: {
  ok: boolean;
  label: string;
  detail: string;
}) {
  return (
    <div className={`check-line ${ok ? "check-ok" : "check-no"}`}>
      <span className="check-mark">
        {ok ? <Check size={12} /> : <AlertTriangle size={12} />}
      </span>
      <span>
        <strong>{label}</strong>
        <em>{detail}</em>
      </span>
    </div>
  );
}

export function EmptyState({
  icon,
  title,
  children,
}: {
  icon: ReactNode;
  title: string;
  children: ReactNode;
}) {
  return (
    <div className="empty-state">
      <div className="empty-icon">{icon}</div>
      <h3>{title}</h3>
      <p>{children}</p>
    </div>
  );
}

import { useState, type FormEvent } from "react";
import { Lock, MapPin, Play, Search } from "lucide-react";
import type { CreateResearchRequest } from "../types.ts";

const PRESETS: Array<{
  label: string;
  city: string;
  category: CreateResearchRequest["category"];
}> = [
  { label: "Galway cafés", city: "Galway, Ireland", category: "cafe" },
  { label: "Bath bakeries", city: "Bath, United Kingdom", category: "bakery" },
  { label: "Porto restaurants", city: "Porto, Portugal", category: "restaurant" },
];

const CATEGORY_OPTIONS: Array<{
  value: CreateResearchRequest["category"];
  label: string;
}> = [
  { value: "cafe", label: "Cafés" },
  { value: "restaurant", label: "Restaurants" },
  { value: "bakery", label: "Bakeries" },
];

export function AssignmentForm({
  onSubmit,
  busy,
}: {
  onSubmit: (input: CreateResearchRequest) => Promise<void>;
  busy: boolean;
}) {
  const [city, setCity] = useState("Galway, Ireland");
  const [category, setCategory] =
    useState<CreateResearchRequest["category"]>("cafe");
  const [count, setCount] = useState(3);

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (busy || city.trim().length < 2) return;
    void onSubmit({ city: city.trim(), category, count });
  };

  return (
    <form className="assignment" onSubmit={submit}>
      <div className="assignment-grid">
        <label className="field city-field">
          <span className="field-label">
            <MapPin size={13} aria-hidden="true" />
            Target market
          </span>
          <input
            value={city}
            onChange={(event) => setCity(event.target.value)}
            placeholder="City and country"
            maxLength={80}
            disabled={busy}
            required
          />
        </label>

        <label className="field">
          <span className="field-label">Prospect category</span>
          <select
            value={category}
            onChange={(event) =>
              setCategory(event.target.value as CreateResearchRequest["category"])
            }
            disabled={busy}
          >
            {CATEGORY_OPTIONS.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        </label>

        <div className="field">
          <span className="field-label">Prospects required</span>
          <div className="count-picker" role="group" aria-label="Prospect count">
            {[1, 2, 3, 4, 5].map((value) => (
              <button
                key={value}
                type="button"
                className={value === count ? "count-active" : ""}
                onClick={() => setCount(value)}
                disabled={busy}
                aria-pressed={value === count}
              >
                {value}
              </button>
            ))}
          </div>
        </div>

        <button className="run-button" type="submit" disabled={busy}>
          {busy ? (
            <>
              <Search size={16} className="spin" aria-hidden="true" />
              Submitting…
            </>
          ) : (
            <>
              <Play size={15} aria-hidden="true" />
              Assign to NOVA
            </>
          )}
        </button>
      </div>

      <div className="assignment-foot">
        <div className="presets" aria-label="Market presets">
          <span>Quick market:</span>
          {PRESETS.map((preset) => (
            <button
              key={preset.label}
              type="button"
              disabled={busy}
              onClick={() => {
                setCity(preset.city);
                setCategory(preset.category);
              }}
            >
              {preset.label}
            </button>
          ))}
        </div>
        <p className="guardrail">
          <Lock size={12} aria-hidden="true" />
          Live public-data lookups only. No outreach, publishing, or spend.
        </p>
      </div>
    </form>
  );
}

import { useMemo, useState } from "react";
import { ChevronRight, Inbox, ListFilter } from "lucide-react";
import type { Task } from "../types.ts";
import {
  STATUS_META,
  StatusBadge,
  formatTimestamp,
  shortId,
} from "./ui.tsx";

type Filter = "ALL" | "ACTIVE" | "COMPLETED" | "FAILED" | "APPROVAL";

const FILTERS: Array<{ value: Filter; label: string }> = [
  { value: "ALL", label: "All" },
  { value: "ACTIVE", label: "Active" },
  { value: "COMPLETED", label: "Done" },
  { value: "FAILED", label: "Failed" },
  { value: "APPROVAL", label: "Approval" },
];

export function TaskQueue({
  tasks,
  selectedId,
  onSelect,
}: {
  tasks: Task[];
  selectedId: string | null;
  onSelect: (id: string) => void;
}) {
  const [filter, setFilter] = useState<Filter>("ALL");

  const visible = useMemo(() => {
    return tasks.filter((task) => {
      if (filter === "ALL") return true;
      if (filter === "ACTIVE")
        return task.status === "QUEUED" || task.status === "RUNNING";
      if (filter === "APPROVAL") return task.status === "AWAITING_APPROVAL";
      return task.status === filter;
    });
  }, [tasks, filter]);

  return (
    <section className="queue panel" aria-label="Task queue">
      <header className="queue-head">
        <div>
          <p className="eyebrow">Durable queue</p>
          <h2>Assignments</h2>
        </div>
        <span className="queue-total">{tasks.length}</span>
      </header>

      <div className="filter-row" role="group" aria-label="Filter assignments">
        <ListFilter size={13} aria-hidden="true" />
        {FILTERS.map((item) => (
          <button
            key={item.value}
            type="button"
            className={filter === item.value ? "filter-active" : ""}
            onClick={() => setFilter(item.value)}
          >
            {item.label}
          </button>
        ))}
      </div>

      <div className="task-list">
        {visible.length === 0 ? (
          <div className="queue-empty">
            <Inbox size={26} aria-hidden="true" />
            <p>
              {tasks.length === 0
                ? "No assignments yet. NOVA is standing by."
                : "No assignments match this filter."}
            </p>
          </div>
        ) : (
          visible.map((task) => {
            const meta = STATUS_META[task.status];
            const result = task.result;
            const prospectCount =
              result && "prospects" in result ? result.prospects.length : null;
            return (
              <button
                type="button"
                key={task.id}
                className={`task-row ${selectedId === task.id ? "task-selected" : ""}`}
                onClick={() => onSelect(task.id)}
              >
                <span className={`task-status-line ${meta.className}`} />
                <span className="task-main">
                  <span className="task-title-row">
                    <span className="task-id">{shortId(task.id)}</span>
                    <StatusBadge status={task.status} />
                  </span>
                  <strong className="task-title">{task.title}</strong>
                  <span className="task-meta">
                    {task.type === "PROSPECT_RESEARCH" ? "NOVA · research" : "ECHO · draft"} ·{" "}
                    {formatTimestamp(task.createdAt)}
                    {prospectCount !== null
                      ? ` · ${prospectCount} prospect${prospectCount === 1 ? "" : "s"}`
                      : ""}
                  </span>
                  {task.status === "RUNNING" ? (
                    <span className="mini-progress">
                      <span style={{ width: `${task.progress.percent}%` }} />
                    </span>
                  ) : null}
                  {task.status === "FAILED" && task.error ? (
                    <span className="task-error-line">
                      {task.error.code} · {task.error.message}
                    </span>
                  ) : null}
                  {task.status === "AWAITING_APPROVAL" ? (
                    <span className="task-approval-line">
                      Operator decision required
                    </span>
                  ) : null}
                </span>
                <ChevronRight size={16} className="task-chevron" aria-hidden="true" />
              </button>
            );
          })
        )}
      </div>
    </section>
  );
}

