  const [initialLoading, setInitialLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [actionBusy, setActionBusy] = useState(false);
  const [toast, setToast] = useState<Toast | null>(null);
  const [clock, setClock] = useState(() => new Date());

  const notify = useCallback((message: string, tone: Toast["tone"] = "info") => {
    setToast({ id: Date.now(), message, tone });
  }, []);

  const loadData = useCallback(async () => {
    setLoadError(null);
    try {
      const [nextTasks, nextSystem] = await Promise.all([
        fetchTasks(),
        fetchSystem(),
      ]);
      setTasks(nextTasks);
      setSystem(nextSystem);
      setConnectedClients(nextSystem.connectedClients);
      setSelectedId((current) => current ?? nextTasks[0]?.id ?? null);
    } catch (error) {
      setLoadError(
        error instanceof Error ? error.message : "Unable to reach the HQ server.",
      );
    } finally {
      setInitialLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadData();
  }, [loadData]);

  useEffect(() => {
    const timer = setInterval(() => setClock(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (!toast) return;
    const timer = setTimeout(() => setToast(null), 6500);
    return () => clearTimeout(timer);
  }, [toast]);

  useEffect(() => {
    let source: EventSource | null = null;
    let retry: ReturnType<typeof setTimeout> | null = null;

    const connect = () => {
      source = new EventSource("/api/events");
      source.onopen = () => {
        setStreamLive(true);
        void fetchSystem()
          .then((next) => {
            setSystem(next);
            setConnectedClients(next.connectedClients);
          })
          .catch(() => undefined);
      };
      source.onerror = () => {
        setStreamLive(false);
      };
      source.addEventListener("snapshot", (event) => {
        try {
          const data = JSON.parse((event as MessageEvent).data) as {
            tasks: Task[];
            connectedClients: number;
          };
          setTasks(
            [...data.tasks].sort((a, b) => b.createdAt.localeCompare(a.createdAt)),
          );
          setConnectedClients(data.connectedClients);
          setSelectedId((current) => current ?? data.tasks[0]?.id ?? null);
          setStreamLive(true);
          setInitialLoading(false);
        } catch {
          // Ignore malformed stream frames; HTTP state remains authoritative.
        }
      });
      source.addEventListener("task", (event) => {
        try {
          const task = JSON.parse((event as MessageEvent).data) as Task;
          setTasks((current) => {
            const next = [task, ...current.filter((item) => item.id !== task.id)];
            return next.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
          });
        } catch {
          // Ignore malformed frame.
        }
      });
    };

    connect();
    retry = setInterval(() => {
      if (source?.readyState === EventSource.CLOSED) {
        connect();
      }
    }, 8000);

    return () => {
      source?.close();
      if (retry) clearInterval(retry);
    };
  }, []);

  const selectedTask = useMemo(
    () => tasks.find((task) => task.id === selectedId) ?? null,
    [tasks, selectedId],
  );

  const counts = useMemo(() => {
    const base: Record<TaskStatus, number> = {
      QUEUED: 0,
      RUNNING: 0,
      COMPLETED: 0,
      FAILED: 0,
      AWAITING_APPROVAL: 0,
    };
    for (const task of tasks) base[task.status] += 1;
    return base;
  }, [tasks]);

  const deliveredProspects = useMemo(
    () =>
      tasks.reduce((total, task) => {
        if (
          task.status === "COMPLETED" &&
          task.result &&
          "prospects" in task.result
        ) {
          return total + task.result.prospects.length;
        }
        return total;
      }, 0),
    [tasks],
  );

  const handleResearch = async (input: CreateResearchRequest) => {
    setSubmitting(true);
    try {
      const task = await submitResearch(input);
      setTasks((current) => [
        task,
        ...current.filter((item) => item.id !== task.id),
      ]);
      setSelectedId(task.id);
      setView("operations");
      notify(`Task ${task.id} queued for NOVA.`, "info");
    } catch (error) {
      notify(
        error instanceof Error ? error.message : "Could not submit the task.",
        "error",
      );
    } finally {
      setSubmitting(false);
    }
  };

  const handleRetry = async (id: string) => {
    setActionBusy(true);
    try {
      const task = await retryTask(id);
      setTasks((current) => [
        task,
        ...current.filter((item) => item.id !== task.id),
      ]);
      setSelectedId(task.id);
      notify("Retry accepted and re-queued.", "info");
    } catch (error) {
      notify(error instanceof Error ? error.message : "Retry failed.", "error");
    } finally {
      setActionBusy(false);
    }
  };

  const handleOutreach = async (parentTaskId: string, prospectId: string) => {
    if (actionBusy) return;
    setActionBusy(true);
    try {
      const task = await submitOutreach(parentTaskId, prospectId);
      setTasks((current) => [
        task,
        ...current.filter((item) => item.id !== task.id),
      ]);
      setSelectedId(task.id);
      setView("operations");
      notify("Local draft created. Awaiting operator approval — nothing sent.", "info");
    } catch (error) {
      notify(
        error instanceof Error ? error.message : "Could not create the draft.",
        "error",
      );
    } finally {
      setActionBusy(false);
    }
  };

  const handleDecision = async (
    id: string,
    decision: "APPROVE" | "REJECT",
    note: string,
  ) => {
    setActionBusy(true);
    try {
      const task = await decideTask(id, {
        decision,
        ...(note.trim() ? { note: note.trim() } : {}),
      });
      setTasks((current) => [
        task,
        ...current.filter((item) => item.id !== task.id),
      ]);
      notify(
        decision === "APPROVE"
          ? "Draft approved for manual use. No message was sent."
          : "Draft rejected. No message was sent.",
        decision === "APPROVE" ? "ok" : "info",
      );
    } catch (error) {
      notify(
        error instanceof Error ? error.message : "Decision could not be recorded.",
        "error",
      );
    } finally {
      setActionBusy(false);
    }
  };

  const sysWithClients = system
    ? { ...system, connectedClients }
    : null;

  const openTask = (id: string) => {
    setSelectedId(id);
    setView("operations");
  };

  return (
    <div className="app">
      <header className="topbar">
        <div className="brand">
          <span className="brand-mark" aria-hidden="true">
            <span>AH</span>
          </span>
          <div>
            <p className="brand-name">AGENT // HQ</p>
            <p className="brand-sub">DEEMANNIE&apos;S DIGITAL · OPERATIONS</p>
          </div>
        </div>

        <nav className="main-nav" aria-label="Primary">
          <button
            type="button"
            className={view === "operations" ? "nav-active" : ""}
            onClick={() => setView("operations")}
          >
            <LayoutDashboard size={15} aria-hidden="true" />
            Operations
          </button>
          <button
            type="button"
            className={view === "approvals" ? "nav-active" : ""}
            onClick={() => setView("approvals")}
          >
            <ShieldAlert size={15} aria-hidden="true" />
            Approvals
            {counts.AWAITING_APPROVAL > 0 ? (
              <span className="nav-badge">{counts.AWAITING_APPROVAL}</span>
            ) : null}
          </button>
          <button
            type="button"
            className={view === "system" ? "nav-active" : ""}
            onClick={() => setView("system")}
          >
            <Server size={15} aria-hidden="true" />
            System
          </button>
        </nav>

        <div className="topbar-status">
          <span className={`live-pill ${streamLive ? "live-on" : "live-off"}`}>
            <Radio size={13} aria-hidden="true" />
            {streamLive ? "STREAM LIVE" : "HTTP ONLY"}
          </span>
          <span className="utc-clock">
            {formatTimestamp(clock.toISOString()).replace(" UTC", "")}
            <em>UTC</em>
          </span>
        </div>
      </header>

      <div className="shell">
        <AgentRail
          tasks={tasks}
          system={sysWithClients}
          connected={streamLive}
        />

        <main className="main">
          {loadError ? (
            <div className="load-error" role="alert">
              <ShieldAlert size={18} />
              <div>
                <strong>HQ server unreachable</strong>
                <p>{loadError}</p>
              </div>
              <button type="button" onClick={() => void loadData()}>
                Reconnect
              </button>
            </div>
          ) : null}

          {view === "operations" ? (
            <>
              <section className="page-intro ops-intro">
                <div>
                  <p className="eyebrow">Mission control</p>
                  <h1>Live operations</h1>
                  <p>
                    Assign real public-data research. Watch the execution record,
                    inspect the evidence, and keep outreach behind a human gate.
                  </p>
                </div>
                <div className="intro-seal">
                  <ShieldCheck size={18} aria-hidden="true" />
                  <div>
                    <strong>NO SIMULATED RUNS</strong>
                    <span>Statuses are server-verified</span>
                  </div>
                </div>
              </section>

              <AssignmentForm onSubmit={handleResearch} busy={submitting} />

              <div className="stats-strip">
                <div>
                  <Activity size={15} aria-hidden="true" />
                  <span>Active</span>
                  <strong>{counts.QUEUED + counts.RUNNING}</strong>
                </div>
                <div>
                  <CheckCircle2 size={15} aria-hidden="true" />
                  <span>Completed</span>
                  <strong>{counts.COMPLETED}</strong>
                </div>
                <div>
                  <Database size={15} aria-hidden="true" />
                  <span>Prospects delivered</span>
                  <strong>{deliveredProspects}</strong>
                </div>
                <div>
                  <BellRing size={15} aria-hidden="true" />
                  <span>Approvals</span>
                  <strong>{counts.AWAITING_APPROVAL}</strong>
                </div>
                <div>
                  <Radio size={15} aria-hidden="true" />
                  <span>SSE clients</span>
                  <strong>{connectedClients}</strong>
                </div>
              </div>

              {initialLoading ? (
                <div className="boot-panel">
                  <span className="boot-scan" />
                  <p>Connecting to the HQ task store…</p>
                </div>
              ) : (
                <div className="ops-grid">
                  <TaskQueue
                    tasks={tasks}
                    selectedId={selectedId}
                    onSelect={setSelectedId}
                  />
                  {tasks.length === 0 ? (
                    <NoTasksBrief />
                  ) : (
                    <TaskDetail
                      task={selectedTask}
                      onRetry={handleRetry}
                      onOutreach={handleOutreach}
                      onDecision={handleDecision}
                      busy={actionBusy}
                      connectedClients={connectedClients}
                    />
                  )}
                </div>
              )}
            </>
          ) : null}

          {view === "approvals" ? (
            <ApprovalsView tasks={tasks} onSelect={openTask} />
          ) : null}

          {view === "system" ? <SystemView system={sysWithClients} /> : null}

          <footer className="foot">
            <span>
              AGENT HQ v2.0 · DEEMANNIE&apos;S DIGITAL ·{" "}
              {tasks.length} durable task{tasks.length === 1 ? "" : "s"} · last
              sync {formatTimestamp(clock.toISOString())}
            </span>
            <span>No hidden sends. No fabricated evidence.</span>
          </footer>
        </main>
      </div>

      {toast ? (
        <div className={`toast toast-${toast.tone}`} role="status">
          <span>{toast.message}</span>
          <button
            type="button"
            aria-label="Dismiss notification"
            onClick={() => setToast(null)}
          >
            <X size={14} />
          </button>
        </div>
      ) : null}
    </div>
  );
}

:root {
  --bg: #05080c;
  --bg-soft: #080d13;
  --panel: #0b1119;
  --panel-2: #0f1721;
  --panel-3: #121c27;
  --line: rgba(188, 214, 226, 0.1);
  --line-strong: rgba(188, 214, 226, 0.2);
  --text: #e8f0f3;
  --muted: #80919c;
  --muted-2: #5d6d77;
  --lime: #bdf46f;
  --lime-dim: rgba(189, 244, 111, 0.12);
  --teal: #58e0c0;
  --blue: #78b8ff;
  --amber: #ffc861;
  --red: #ff7373;
  --violet: #b29dff;
  --mono: ui-monospace, "SFMono-Regular", "Cascadia Mono", "Roboto Mono",
    Menlo, Consolas, monospace;
  --sans: "Inter", "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont,
    "Helvetica Neue", sans-serif;
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.5;
}

body {
  background-image:
    radial-gradient(circle at 12% 0%, rgba(88, 224, 192, 0.06), transparent 32%),
    radial-gradient(circle at 85% 8%, rgba(189, 244, 111, 0.05), transparent 30%),
    linear-gradient(rgba(255, 255, 255, 0.018) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.018) 1px, transparent 1px);
  background-size: auto, auto, 44px 44px, 44px 44px;
  background-attachment: fixed;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

a {
  color: var(--teal);
  text-decoration: none;
}

a:hover {
  color: var(--lime);
}

::selection {
  background: var(--lime);
  color: #0b1208;
}

.app {
  min-height: 100vh;
}

.eyebrow {
  margin: 0 0 4px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted-2);
}

/* ---------- top bar ---------- */

.topbar {
  position: sticky;
  top: 0;
  z-index: 40;
  display: grid;
  grid-template-columns: minmax(250px, 1fr) auto minmax(250px, 1fr);
  align-items: center;
  gap: 18px;
  height: 68px;
  padding: 0 26px;
  border-bottom: 1px solid var(--line);
  background: rgba(5, 8, 12, 0.86);
  backdrop-filter: blur(16px);
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid rgba(189, 244, 111, 0.5);
  background:
    linear-gradient(135deg, rgba(189, 244, 111, 0.18), transparent 65%),
    #0a1015;
  clip-path: polygon(18% 0, 100% 0, 100% 82%, 82% 100%, 0 100%, 0 18%);
}

.brand-mark span {
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--lime);
}

.brand-name {
  margin: 0;
  font-family: var(--mono);
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.brand-sub {
  margin: 0;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.16em;
  color: var(--muted-2);
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.02);
}

.main-nav button {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 13px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  transition: background 160ms ease, color 160ms ease;
}

.main-nav button:hover {
  color: var(--text);
  background: rgba(255, 255, 255, 0.04);
}

.main-nav button.nav-active {
  color: #0b1208;
  background: var(--lime);
}

.nav-badge {
  min-width: 16px;
  padding: 1px 4px;
  border-radius: 8px;
  background: var(--amber);
  color: #211703;
  font-size: 9px;
  font-weight: 700;
  line-height: 1.4;
}

.topbar-status {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 16px;
}

.live-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 9px;
  border: 1px solid var(--line);
  border-radius: 20px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  color: var(--muted);
}

.live-on {
  border-color: rgba(88, 224, 192, 0.28);
  color: var(--teal);
  background: rgba(88, 224, 192, 0.07);
}

.live-on svg {
  animation: pulse 2.4s ease-in-out infinite;
}

.live-off {
  border-color: rgba(255, 115, 115, 0.3);
  color: var(--red);
}

.utc-clock {
  display: flex;
  align-items: baseline;
  gap: 5px;
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: 0.04em;
  color: var(--text);
}

.utc-clock em {
  font-style: normal;
  font-size: 8px;
  color: var(--muted-2);
}

/* ---------- layout ---------- */

.shell {
  display: grid;
  grid-template-columns: 300px minmax(0, 1fr);
  gap: 22px;
  width: 100%;
  max-width: 1720px;
  margin: 0 auto;
  padding: 22px 26px 40px;
}

.main {
  min-width: 0;
}

.rail {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.panel {
  border: 1px solid var(--line);
  border-radius: 8px;
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.025), transparent 40%),
    var(--panel);
}

.rail-panel {
  padding: 14px;
}

.rail-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
  color: var(--muted-2);
}

.rail-head h2 {
  margin: 0;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}

.rail-count {
  font-family: var(--mono);
  font-size: 9px;
  color: var(--muted-2);
}

/* ---------- nova card ---------- */

.nova-card {
  position: relative;
  overflow: hidden;
  padding: 18px;
  border: 1px solid rgba(189, 244, 111, 0.22);
  border-radius: 8px;
  background:
    radial-gradient(circle at 85% 0%, rgba(189, 244, 111, 0.12), transparent 45%),
    linear-gradient(160deg, #101820, #0a0f15);
}

.nova-card::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 3px,
    rgba(255, 255, 255, 0.012) 3px,
    rgba(255, 255, 255, 0.012) 4px
  );
}

.nova-active {
  border-color: rgba(88, 224, 192, 0.35);
  box-shadow: inset 0 0 40px rgba(88, 224, 192, 0.04);
}

.nova-orbit {
  position: relative;
  float: right;
  display: grid;
  place-items: center;
  width: 62px;
  height: 62px;
  margin: -2px 0 6px 10px;
}

.orbit-ring {
  position: absolute;
  inset: 0;
  border: 1px dashed rgba(189, 244, 111, 0.38);
  border-radius: 50%;
}

.nova-active .orbit-ring {
  animation: spin 8s linear infinite;
  border-color: rgba(88, 224, 192, 0.55);
}

.nova-core {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border: 1px solid rgba(189, 244, 111, 0.4);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(189, 244, 111, 0.2), #0a1115 70%);
  color: var(--lime);
  font-family: var(--mono);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: -0.04em;
}

.nova-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.nova-head h2 {
  margin: 0;
  font-family: var(--mono);
  font-size: 25px;
  letter-spacing: 0.08em;
}

.agent-state {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 7px;
  border: 1px solid var(--line);
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.09em;
  color: var(--muted);
  white-space: nowrap;
}

.agent-state .dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--muted-2);
}

.agent-state.state-live {
  color: var(--teal);
  border-color: rgba(88, 224, 192, 0.3);
}

.agent-state.state-live .dot {
  background: var(--teal);
  box-shadow: 0 0 8px var(--teal);
  animation: pulse 1.6s ease-in-out infinite;
}

.nova-detail {
  margin: 12px 0 16px;
  min-height: 36px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.5;
}

.nova-metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  padding: 10px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.nova-metrics div {
  display: flex;
  flex-direction: column;
}

.nova-metrics strong {
  font-family: var(--mono);
  font-size: 21px;
  font-weight: 500;
  color: var(--lime);
  line-height: 1.2;
}

.nova-metrics span {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.07em;
  color: var(--muted-2);
  text-transform: uppercase;
}

.nova-last {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.03em;
}

.nova-last svg {
  color: var(--teal);
  flex: none;
}

/* ---------- agent roster ---------- */

.agent-list {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.agent-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px;
  border-radius: 5px;
  transition: background 150ms ease;
}

.agent-row:hover {
  background: rgba(255, 255, 255, 0.025);
}

.agent-icon {
  display: grid;
  place-items: center;
  flex: none;
  width: 28px;
  height: 28px;
  border: 1px solid var(--line);
  border-radius: 4px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.02);
}

.agent-icon.agent-live {
  color: var(--teal);
  border-color: rgba(88, 224, 192, 0.24);
  background: rgba(88, 224, 192, 0.06);
}

.agent-icon.agent-gated {
  color: var(--amber);
  border-color: rgba(255, 200, 97, 0.22);
}

.agent-copy {
  min-width: 0;
  flex: 1;
}

.agent-copy > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.agent-copy strong {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.1em;
}

.agent-tag {
  padding: 1px 5px;
  border: 1px solid var(--line);
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  color: var(--muted-2);
}

.tag-live {
  color: var(--teal);
  border-color: rgba(88, 224, 192, 0.25);
}

.tag-gated {
  color: var(--amber);
  border-color: rgba(255, 200, 97, 0.25);
}

.agent-copy > span {
  display: block;
  font-size: 10px;
  color: var(--muted);
}

.agent-copy em {
  display: block;
  margin-top: 1px;
  font-style: normal;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
}

/* ---------- bridge ---------- */

.bridge-status {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.bridge-row {
  display: grid;
  grid-template-columns: 18px 1fr auto;
  align-items: center;
  gap: 7px;
  padding: 7px 4px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.04);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
}

.bridge-row svg {
  color: var(--muted-2);
}

.bridge-row b {
  color: var(--teal);
  font-size: 8px;
  letter-spacing: 0.08em;
}

.bridge-row b.blocked {
  color: var(--red);
}

.bridge-provider {
  margin: 9px 4px 0;
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1.5;
  color: var(--muted-2);
  overflow-wrap: anywhere;
}

.truth-card {
  padding: 13px 14px;
  border: 1px dashed rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.015);
}

.truth-card p:not(.eyebrow) {
  margin: 6px 0 9px;
  font-size: 10px;
  line-height: 1.55;
  color: var(--muted);
}

.truth-card strong {
  color: var(--text);
  font-weight: 600;
}

.truth-link {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
}

/* ---------- intro ---------- */

.page-intro {
  margin-bottom: 18px;
}

.page-intro h1 {
  margin: 0 0 6px;
  font-size: clamp(28px, 4vw, 38px);
  font-weight: 600;
  letter-spacing: -0.035em;
  line-height: 1.05;
}

.page-intro > p:not(.eyebrow) {
  max-width: 760px;
  margin: 0;
  color: var(--muted);
  font-size: 13px;
}

.ops-intro {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
}

.intro-seal {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border: 1px solid rgba(189, 244, 111, 0.22);
  border-radius: 6px;
  background: rgba(189, 244, 111, 0.045);
  color: var(--lime);
  white-space: nowrap;
}

.intro-seal div {
  display: flex;
  flex-direction: column;
}

.intro-seal strong {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.1em;
}

.intro-seal span {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
}

.intro-flags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
}

.intro-flags span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 9px;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.02);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.06em;
  color: var(--muted);
  text-transform: uppercase;
}

.intro-flags svg {
  color: var(--teal);
}

/* ---------- assignment form ---------- */

.assignment {
  padding: 16px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background:
    linear-gradient(120deg, rgba(88, 224, 192, 0.035), transparent 40%),
    var(--panel-2);
}

.assignment-grid {
  display: grid;
  grid-template-columns: minmax(210px, 1.5fr) minmax(150px, 0.8fr) minmax(
      180px,
      0.9fr
    ) auto;
  align-items: end;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  display: flex;
  align-items: center;
  gap: 5px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

.field input,
.field select {
  width: 100%;
  height: 38px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: #080d13;
  color: var(--text);
  font-size: 12px;
  outline: none;
  transition: border-color 150ms ease, box-shadow 150ms ease;
}

.field select {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--muted) 50%),
    linear-gradient(135deg, var(--muted) 50%, transparent 50%);
  background-position:
    calc(100% - 14px) 16px,
    calc(100% - 9px) 16px;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

.field input:focus,
.field select:focus,
.decision-box textarea:focus {
  border-color: rgba(189, 244, 111, 0.55);
  box-shadow: 0 0 0 3px rgba(189, 244, 111, 0.08);
}

.count-picker {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 3px;
  height: 38px;
  padding: 3px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: #080d13;
}

.count-picker button {
  border: 0;
  border-radius: 2px;
  background: transparent;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 11px;
}

.count-picker button:hover {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text);
}

.count-picker button.count-active {
  background: var(--lime);
  color: #0d1509;
  font-weight: 700;
}

.run-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 38px;
  padding: 0 18px;
  border: 0;
  border-radius: 4px;
  background: var(--lime);
  color: #0c1308;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
  transition: transform 120ms ease, box-shadow 150ms ease, opacity 150ms ease;
}

.run-button:hover:not(:disabled) {
  box-shadow: 0 0 22px rgba(189, 244, 111, 0.2);
  transform: translateY(-1px);
}

.run-button:disabled {
  opacity: 0.55;
  cursor: wait;
}

.assignment-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 12px;
  padding-top: 11px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.presets {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
}

.presets > span {
  margin-right: 2px;
}

.presets button {
  padding: 3px 7px;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: transparent;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
}

.presets button:hover:not(:disabled) {
  border-color: rgba(189, 244, 111, 0.3);
  color: var(--lime);
}

.guardrail {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 0;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
  text-align: right;
}

.guardrail svg {
  flex: none;
  color: var(--amber);
}

/* ---------- stats ---------- */

.stats-strip {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1px;
  margin: 14px 0;
  border: 1px solid var(--line);
  border-radius: 6px;
  overflow: hidden;
  background: var(--line);
}

.stats-strip > div {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 8px;
  padding: 9px 12px;
  background: var(--panel);
}

.stats-strip svg {
  color: var(--muted-2);
}

.stats-strip span {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--muted-2);
}

.stats-strip strong {
  font-family: var(--mono);
  font-size: 15px;
  font-weight: 500;
  color: var(--text);
}

/* ---------- ops grid / queue ---------- */

.ops-grid {
  display: grid;
  grid-template-columns: minmax(280px, 350px) minmax(0, 1fr);
  align-items: start;
  gap: 14px;
}

.queue {
  position: sticky;
  top: 90px;
  overflow: hidden;
}

.queue-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 14px 14px 10px;
}

.queue-head h2 {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.queue-total {
  display: grid;
  place-items: center;
  min-width: 28px;
  height: 24px;
  padding: 0 7px;
  border: 1px solid var(--line);
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--muted);
}

.filter-row {
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 0 10px 10px;
  color: var(--muted-2);
  overflow-x: auto;
}

.filter-row button {
  padding: 4px 7px;
  border: 0;
  border-radius: 3px;
  background: transparent;
  color: var(--muted-2);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  white-space: nowrap;
}

.filter-row button:hover {
  color: var(--text);
}

.filter-row button.filter-active {
  background: rgba(255, 255, 255, 0.07);
  color: var(--text);
}

.task-list {
  max-height: calc(100vh - 250px);
  overflow-y: auto;
  border-top: 1px solid var(--line);
}

.task-row {
  position: relative;
  display: flex;
  align-items: stretch;
  gap: 9px;
  width: 100%;
  padding: 11px 12px 11px 14px;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.045);
  background: transparent;
  text-align: left;
  transition: background 140ms ease;
}

.task-row:hover {
  background: rgba(255, 255, 255, 0.025);
}

.task-row.task-selected {
  background:
    linear-gradient(90deg, rgba(189, 244, 111, 0.06), transparent 70%),
    rgba(255, 255, 255, 0.02);
}

.task-status-line {
  flex: none;
  width: 2px;
  border-radius: 2px;
  background: var(--muted-2);
}

.task-status-line.status-queued {
  background: var(--muted);
}
.task-status-line.status-running {
  background: var(--blue);
  box-shadow: 0 0 8px rgba(120, 184, 255, 0.5);
}
.task-status-line.status-completed {
  background: var(--teal);
}
.task-status-line.status-failed {
  background: var(--red);
}
.task-status-line.status-approval {
  background: var(--amber);
}

.task-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1;
  gap: 3px;
}

.task-title-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.task-id {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.06em;
  color: var(--muted-2);
}

.task-title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--text);
}

.task-meta {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
  line-height: 1.4;
}

.task-error-line {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--red);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.task-approval-line {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--amber);
}

.task-chevron {
  align-self: center;
  flex: none;
  color: var(--muted-2);
}

.mini-progress {
  display: block;
  height: 2px;
  margin-top: 3px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.mini-progress span {
  display: block;
  height: 100%;
  background: var(--blue);
  transition: width 400ms ease;
}

.queue-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 32px 20px;
  color: var(--muted-2);
  text-align: center;
}

.queue-empty p {
  margin: 0;
  font-size: 11px;
}

/* ---------- status badges ---------- */

.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 7.5px;
  font-weight: 500;
  letter-spacing: 0.07em;
  white-space: nowrap;
}

.status-queued {
  color: var(--muted);
  border-color: rgba(128, 145, 156, 0.25);
  background: rgba(128, 145, 156, 0.06);
}

.status-running {
  color: var(--blue);
  border-color: rgba(120, 184, 255, 0.27);
  background: rgba(120, 184, 255, 0.07);
}

.status-completed {
  color: var(--teal);
  border-color: rgba(88, 224, 192, 0.28);
  background: rgba(88, 224, 192, 0.07);
}

.status-failed {
  color: var(--red);
  border-color: rgba(255, 115, 115, 0.28);
  background: rgba(255, 115, 115, 0.07);
}

.status-approval {
  color: var(--amber);
  border-color: rgba(255, 200, 97, 0.3);
  background: rgba(255, 200, 97, 0.07);
}

/* ---------- detail ---------- */

.detail-panel {
  padding: 18px;
  min-width: 0;
}

.detail-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}

.detail-head h2 {
  margin: 0 0 4px;
  font-size: clamp(17px, 2.2vw, 22px);
  font-weight: 600;
  letter-spacing: -0.025em;
  line-height: 1.25;
}

.detail-brief {
  max-width: 820px;
  margin: 0;
  color: var(--muted);
  font-size: 11.5px;
}

.detail-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 14px;
  margin: 12px 0;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
}

.detail-meta span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.detail-meta .mode-tag {
  margin-left: auto;
  padding: 2px 6px;
  border: 1px solid rgba(189, 244, 111, 0.16);
  border-radius: 3px;
  color: var(--muted);
  background: rgba(189, 244, 111, 0.04);
}

.progress-card {
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.015);
}

.progress-copy {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 8px;
}

.progress-copy div {
  display: flex;
  flex-direction: column;
}

.progress-copy strong {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.09em;
  color: var(--text);
}

.progress-copy > span {
  font-family: var(--mono);
  font-size: 13px;
  color: var(--lime);
}

.progress-track {
  height: 4px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.07);
  overflow: hidden;
}

.progress-track span {
  display: block;
  height: 100%;
  border-radius: 3px;
  background: var(--lime);
  transition: width 450ms ease;
}

.progress-running span {
  background: linear-gradient(90deg, var(--blue), var(--teal));
  background-size: 200% 100%;
  animation: shimmer 1.8s linear infinite;
}

.progress-failed span {
  background: var(--red);
}

.progress-awaiting_approval span {
  background: var(--amber);
}

.progress-message {
  margin: 8px 0 0;
  color: var(--muted);
  font-size: 11px;
}

.progress-attempt {
  margin: 5px 0 0;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
}

/* ---------- error + delivery ---------- */

.error-card {
  margin-top: 12px;
  padding: 12px;
  border: 1px solid rgba(255, 115, 115, 0.3);
  border-radius: 6px;
  background: rgba(255, 115, 115, 0.05);
}

.error-title {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--red);
}

.error-title strong {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.06em;
}

.error-title span {
  margin-left: auto;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
}

.error-card > p {
  margin: 7px 0;
  font-size: 12px;
}

.error-detail {
  margin: 0;
  padding: 8px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.25);
  font-family: var(--mono);
  font-size: 9px;
  color: var(--muted);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.error-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 9px;
}

.error-actions > span {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
}

.delivery-card {
  margin-top: 12px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgba(88, 224, 192, 0.02);
}

.delivery-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.delivery-head strong {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.05em;
  color: var(--teal);
}

.delivery-seal {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 8px;
  border: 1px solid var(--line);
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
}

.seal-ok {
  color: var(--teal);
  border-color: rgba(88, 224, 192, 0.3);
  background: rgba(88, 224, 192, 0.06);
}

.seal-idle {
  color: var(--muted-2);
}

.check-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px 16px;
}

.check-line {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  padding: 5px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.04);
}

.check-mark {
  display: grid;
  place-items: center;
  flex: none;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  border: 1px solid var(--line);
}

.check-ok .check-mark {
  color: var(--teal);
  border-color: rgba(88, 224, 192, 0.3);
}

.check-no .check-mark {
  color: var(--amber);
  border-color: rgba(255, 200, 97, 0.3);
}

.check-line > span:last-child {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.check-line strong {
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.04em;
  color: var(--text);
  font-weight: 500;
}

.check-line em {
  font-style: normal;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
  overflow-wrap: anywhere;
}

/* ---------- report ---------- */

.report {
  margin-top: 16px;
}

.report-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.report-title {
  display: flex;
  align-items: center;
  gap: 10px;
}

.report-icon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1px solid rgba(189, 244, 111, 0.24);
  border-radius: 5px;
  background: rgba(189, 244, 111, 0.05);
  color: var(--lime);
}

.report-title h3 {
  margin: 0;
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.report-stamp {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  text-align: right;
}

.report-stamp span {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.report-stamp strong {
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 500;
  color: var(--muted);
}

.report-summary {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 1px;
  margin: 12px 0 14px;
  border: 1px solid var(--line);
  border-radius: 5px;
  overflow: hidden;
  background: var(--line);
}

.report-summary div {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 9px;
  background: var(--panel);
}

.report-summary span {
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted-2);
}

.report-summary strong {
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
  color: var(--text);
  overflow-wrap: anywhere;
}

.prospect-stack {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.prospect {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 6px;
  background:
    linear-gradient(150deg, rgba(255, 255, 255, 0.02), transparent 35%),
    #090f16;
}

.prospect-head {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  padding: 13px 14px 9px;
}

.prospect-rank {
  display: grid;
  place-items: center;
  flex: none;
  width: 31px;
  height: 31px;
  border: 1px solid rgba(189, 244, 111, 0.25);
  border-radius: 4px;
  background: rgba(189, 244, 111, 0.05);
  color: var(--lime);
  font-family: var(--mono);
  font-size: 11px;
}

.prospect-name {
  flex: 1;
  min-width: 0;
}

.prospect-name h4 {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.015em;
}

.prospect-name p {
  display: flex;
  align-items: flex-start;
  gap: 4px;
  margin: 3px 0 0;
  font-size: 10px;
  color: var(--muted);
}

.prospect-name p svg {
  margin-top: 2px;
  flex: none;
}

.opportunity {
  display: flex;
  align-items: center;
  gap: 7px;
  flex: none;
  text-align: right;
}

.opportunity-score {
  font-family: var(--mono);
  font-size: 22px;
  line-height: 1;
  font-weight: 500;
}

.opportunity > span:last-child {
  display: flex;
  flex-direction: column;
  font-family: var(--mono);
  font-size: 7px;
  color: var(--muted-2);
  line-height: 1.35;
}

.opportunity > span:last-child strong {
  font-size: 8px;
  letter-spacing: 0.07em;
}

.opportunity-high .opportunity-score,
.opportunity-high > span:last-child strong {
  color: var(--red);
}

.opportunity-medium .opportunity-score,
.opportunity-medium > span:last-child strong {
  color: var(--amber);
}

.opportunity-low .opportunity-score,
.opportunity-low > span:last-child strong {
  color: var(--teal);
}

.opportunity-track {
  height: 2px;
  margin: 0 14px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
}

.opportunity-track span {
  display: block;
  height: 100%;
}

.fill-high {
  background: linear-gradient(90deg, var(--amber), var(--red));
}
.fill-medium {
  background: var(--amber);
}
.fill-low {
  background: var(--teal);
}

.website-strip {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 10px 14px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.02);
}

.website-icon {
  display: grid;
  place-items: center;
  flex: none;
  width: 27px;
  height: 27px;
  border-radius: 4px;
  background: rgba(88, 224, 192, 0.08);
  color: var(--teal);
}

.website-strip > div {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1;
}

.website-strip > div > span {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted-2);
}

.website-strip a {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--teal);
  overflow-wrap: anywhere;
}

.website-strip strong {
  font-size: 11px;
  color: var(--text);
}

.website-http {
  font-family: var(--mono);
  font-size: 7.5px;
  color: var(--muted-2);
  white-space: nowrap;
}

.verify-badge {
  padding: 2px 6px;
  border: 1px solid var(--line);
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.07em;
  white-space: nowrap;
}

.verify-good {
  color: var(--teal);
  border-color: rgba(88, 224, 192, 0.28);
  background: rgba(88, 224, 192, 0.06);
}

.verify-warn {
  color: var(--amber);
  border-color: rgba(255, 200, 97, 0.28);
}

.verify-bad {
  color: var(--red);
  border-color: rgba(255, 115, 115, 0.28);
}

.opportunity-summary {
  margin: 0 14px 10px;
  font-size: 11px;
  color: var(--muted);
}

.prospect-columns {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 14px;
  padding: 0 14px 10px;
}

.prospect-block h5,
.signals h5 {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 0 0 6px;
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 500;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--muted);
}

.prospect-block h5 svg {
  color: var(--teal);
}

.fact-list,
.assumption-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fact-list li {
  padding-left: 9px;
  border-left: 1px solid rgba(88, 224, 192, 0.22);
  font-size: 10.5px;
  color: #c4d0d6;
}

.fact-list li > span:first-child {
  display: block;
}

.assumption-list li {
  position: relative;
  padding-left: 10px;
  font-size: 10px;
  color: var(--muted);
}

.assumption-list li::before {
  content: "?";
  position: absolute;
  left: 0;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--amber);
}

.ref-row {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 3px;
  margin-top: 3px;
}

.ref-chip {
  padding: 0 4px;
  border: 1px solid var(--line);
  border-radius: 2px;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.04em;
  color: var(--muted-2);
  background: rgba(255, 255, 255, 0.02);
}

.signals {
  padding: 0 14px 11px;
}

.signal-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.signal {
  padding: 7px 8px;
  border: 1px solid rgba(255, 255, 255, 0.055);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.015);
}

.signal-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 6px;
}

.signal-top strong {
  font-size: 9.5px;
  font-weight: 500;
  color: #d7e2e7;
}

.signal-top > span {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--amber);
}

.signal p {
  margin: 3px 0 0;
  font-size: 9px;
  color: var(--muted-2);
}

.prospect-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 14px;
  border-top: 1px solid var(--line);
  background: rgba(0, 0, 0, 0.14);
}

.prospect-foot > span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--mono);
  font-size: 7.5px;
  color: var(--muted-2);
}

.prospect-actions {
  display: flex;
  align-items: center;
  gap: 5px;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 6px 10px;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.03);
  color: var(--text);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.04em;
  transition: background 140ms ease, border-color 140ms ease;
}

.button:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.07);
  border-color: var(--line-strong);
}

.button:disabled {
  opacity: 0.5;
  cursor: wait;
}

.button.ghost {
  background: transparent;
  color: var(--muted);
}

.button.outline {
  border-color: rgba(255, 200, 97, 0.25);
  color: var(--amber);
  background: rgba(255, 200, 97, 0.04);
}

.button.secondary {
  border-color: rgba(120, 184, 255, 0.25);
  color: var(--blue);
}

.button.approve {
  border-color: var(--lime);
  background: var(--lime);
  color: #0d1509;
  font-weight: 700;
}

.button.danger {
  border-color: rgba(255, 115, 115, 0.3);
  color: var(--red);
  background: rgba(255, 115, 115, 0.05);
}

.source-panel {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 0;
  border-top: 1px solid var(--line);
  background: var(--line);
}

.source-item {
  padding: 9px 14px;
  background: #080d13;
}

.source-top {
  display: flex;
  align-items: center;
  gap: 7px;
}

.source-kind {
  padding: 1px 4px;
  border: 1px solid var(--line);
  border-radius: 2px;
  font-family: var(--mono);
  font-size: 6.5px;
  letter-spacing: 0.06em;
  color: var(--muted-2);
}

.source-top a {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  color: var(--teal);
  overflow-wrap: anywhere;
}

.source-item p {
  margin: 3px 0;
  font-size: 9px;
  color: var(--muted);
  overflow-wrap: anywhere;
}

.source-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 12px;
  font-family: var(--mono);
  font-size: 7px;
  color: var(--muted-2);
}

.hash {
  color: var(--violet);
}

.method-card {
  margin-top: 12px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.015);
}

.method-card summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  cursor: pointer;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  list-style: none;
}

.method-card summary::-webkit-details-marker {
  display: none;
}

.method-card[open] summary svg {
  transform: rotate(180deg);
}

.method-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  padding: 0 12px 12px;
  border-top: 1px solid var(--line);
}

.method-grid h4 {
  margin: 10px 0 4px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.method-grid ol,
.method-grid ul {
  margin: 0;
  padding-left: 15px;
  font-size: 9.5px;
  color: var(--muted);
}

.method-grid li {
  margin-bottom: 3px;
}

/* ---------- timeline ---------- */

.timeline {
  margin-top: 16px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.timeline-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 9px;
}

.timeline-head h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}

.timeline-head > span {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
}

.timeline ol {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.timeline li {
  position: relative;
  display: flex;
  gap: 9px;
  padding: 0 0 10px 0;
}

.timeline li::before {
  content: "";
  position: absolute;
  left: 3px;
  top: 9px;
  bottom: -1px;
  width: 1px;
  background: rgba(255, 255, 255, 0.07);
}

.timeline li:last-child::before {
  display: none;
}

.event-dot {
  position: relative;
  z-index: 1;
  flex: none;
  width: 7px;
  height: 7px;
  margin-top: 5px;
  border: 1px solid var(--muted-2);
  border-radius: 50%;
  background: var(--panel);
}

.event-status .event-dot {
  border-color: var(--lime);
  background: var(--lime);
}

.event-error .event-dot {
  border-color: var(--red);
  background: var(--red);
}

.event-delivery .event-dot {
  border-color: var(--teal);
  background: var(--teal);
}

.event-progress .event-dot {
  border-color: var(--blue);
}

.event-meta {
  display: block;
  font-family: var(--mono);
  font-size: 7.5px;
  color: var(--muted-2);
}

.timeline li p {
  margin: 2px 0 0;
  font-size: 10px;
  color: var(--muted);
}

/* ---------- outreach ---------- */

.outreach {
  margin-top: 16px;
  border: 1px solid rgba(255, 200, 97, 0.28);
  border-radius: 6px;
  background:
    linear-gradient(150deg, rgba(255, 200, 97, 0.045), transparent 40%),
    #0b1016;
  overflow: hidden;
}

.outreach-head {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 12px 14px;
  border-bottom: 1px solid rgba(255, 200, 97, 0.16);
  color: var(--amber);
}

.outreach-head h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}

.not-sent {
  margin-left: auto;
  padding: 3px 7px;
  border: 1px solid rgba(255, 115, 115, 0.3);
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--red);
  white-space: nowrap;
}

.draft-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  padding: 8px 14px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  font-family: var(--mono);
  font-size: 7.5px;
  color: var(--muted-2);
}

.draft-box {
  margin: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: #070b10;
}

.draft-box > div {
  display: flex;
  flex-direction: column;
  padding: 9px 11px;
  border-bottom: 1px solid var(--line);
}

.draft-box > div span {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted-2);
}

.draft-box > div strong {
  font-size: 11px;
  font-weight: 500;
}

.draft-box pre {
  margin: 0;
  padding: 12px;
  font-family: var(--mono);
  font-size: 10px;
  line-height: 1.65;
  color: #c6d2d8;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.approval-note {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  margin: 0 14px 12px;
  padding: 8px 10px;
  border: 1px dashed rgba(255, 200, 97, 0.25);
  border-radius: 4px;
  color: var(--amber);
}

.approval-note p {
  margin: 0;
  font-family: var(--mono);
  font-size: 8px;
  line-height: 1.5;
}

.decision-box {
  padding: 12px 14px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.015);
}

.decision-box label {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.decision-box label > span {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
}

.decision-box textarea {
  min-height: 58px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: #070b10;
  font-size: 11px;
  resize: vertical;
  outline: none;
}

.decision-actions {
  display: flex;
  justify-content: flex-end;
  gap: 7px;
  margin-top: 9px;
}

.decision-caveat {
  margin: 8px 0 0;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
  text-align: right;
}

.decision-result {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin: 0 14px 14px;
  padding: 10px;
  border-radius: 4px;
}

.result-ok {
  border: 1px solid rgba(88, 224, 192, 0.25);
  background: rgba(88, 224, 192, 0.05);
  color: var(--teal);
}

.result-reject {
  border: 1px solid rgba(255, 115, 115, 0.25);
  background: rgba(255, 115, 115, 0.05);
  color: var(--red);
}

.decision-result strong {
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.08em;
}

.decision-result p {
  margin: 2px 0;
  font-size: 10px;
  color: var(--muted);
}

.decision-result span {
  font-family: var(--mono);
  font-size: 7.5px;
  color: var(--muted-2);
}

/* ---------- empty / briefing ---------- */

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 230px;
  padding: 30px;
  text-align: center;
}

.empty-icon {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  margin-bottom: 12px;
  border: 1px dashed var(--line-strong);
  border-radius: 50%;
  color: var(--muted-2);
}

.empty-state h3 {
  margin: 0 0 5px;
  font-size: 15px;
  font-weight: 600;
}

.empty-state p {
  max-width: 380px;
  margin: 0;
  font-size: 11px;
  color: var(--muted);
}

.briefing {
  padding: 26px;
  background:
    radial-gradient(circle at 20% 0%, rgba(189, 244, 111, 0.06), transparent 42%),
    var(--panel);
}

.briefing-art {
  position: relative;
  display: grid;
  place-items: center;
  width: 76px;
  height: 76px;
  margin-bottom: 14px;
  border: 1px solid rgba(189, 244, 111, 0.2);
  border-radius: 50%;
  color: var(--lime);
}

.briefing-art > span {
  position: absolute;
  inset: 7px;
  border: 1px dashed rgba(189, 244, 111, 0.2);
  border-radius: 50%;
  animation: spin 18s linear infinite;
}

.briefing h2 {
  max-width: 520px;
  margin: 0 0 8px;
  font-size: clamp(23px, 3vw, 31px);
  font-weight: 600;
  letter-spacing: -0.035em;
  line-height: 1.1;
}

.briefing-lead {
  max-width: 600px;
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.briefing-steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-top: 18px;
}

.briefing-steps > div {
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.015);
}

.briefing-steps > div > span {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--lime);
}

.briefing-steps strong {
  display: block;
  margin: 3px 0;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.06em;
}

.briefing-steps p {
  margin: 0;
  font-size: 9.5px;
  color: var(--muted-2);
}

.briefing-guard {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
}

.briefing-guard svg {
  flex: none;
  color: var(--amber);
}

/* ---------- views ---------- */

.view-stack {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.approval-list {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 0 14px 14px;
}

.approval-card {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.015);
  text-align: left;
  transition: border-color 140ms ease, background 140ms ease;
}

.approval-card:hover {
  border-color: rgba(255, 200, 97, 0.28);
  background: rgba(255, 200, 97, 0.03);
}

.approval-icon {
  display: grid;
  place-items: center;
  flex: none;
  width: 38px;
  height: 38px;
  border: 1px solid rgba(255, 200, 97, 0.25);
  border-radius: 4px;
  color: var(--amber);
  background: rgba(255, 200, 97, 0.05);
}

.approval-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-width: 0;
}

.approval-top {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.approval-top strong {
  font-size: 12px;
  font-weight: 500;
}

.approval-subject {
  font-size: 10.5px;
  color: var(--muted);
}

.approval-meta {
  font-family: var(--mono);
  font-size: 7.5px;
  color: var(--muted-2);
}

.approval-open {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: none;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--amber);
}

.decision-list {
  display: flex;
  flex-direction: column;
  padding: 0 14px 14px;
}

.decision-row {
  display: grid;
  grid-template-columns: 20px 1fr auto 150px;
  align-items: center;
  gap: 8px;
  padding: 8px;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.045);
  background: transparent;
  text-align: left;
  font-size: 10px;
  color: var(--muted);
}

.decision-row:hover {
  background: rgba(255, 255, 255, 0.02);
}

.decision-row span:nth-child(3),
.decision-row span:nth-child(4) {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
}

.text-ok {
  color: var(--teal);
}
.text-bad {
  color: var(--red);
}

.muted-copy {
  margin: 0;
  padding: 0 14px 16px;
  font-size: 11px;
  color: var(--muted-2);
}

.capability-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  padding: 0 14px 14px;
}

.capability {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.015);
}

.capability-icon {
  display: grid;
  place-items: center;
  flex: none;
  width: 32px;
  height: 32px;
  border: 1px solid var(--line);
  border-radius: 4px;
  color: var(--teal);
}

.capability-blocked .capability-icon {
  color: var(--red);
  border-color: rgba(255, 115, 115, 0.2);
}

.capability-standby .capability-icon {
  color: var(--amber);
}

.capability-status {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.09em;
  color: var(--muted-2);
}

.capability-live .capability-status {
  color: var(--teal);
}

.capability-blocked .capability-status {
  color: var(--red);
}

.capability strong {
  display: block;
  margin: 1px 0;
  font-size: 11px;
  font-weight: 500;
}

.capability p {
  margin: 0;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
  overflow-wrap: anywhere;
}

.system-columns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.protocol {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0 14px 14px;
  list-style: none;
}

.protocol li {
  display: flex;
  gap: 10px;
  padding: 9px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.045);
}

.protocol li > span {
  flex: none;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--lime);
}

.protocol strong {
  display: block;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.06em;
}

.protocol p {
  margin: 2px 0 0;
  font-size: 10px;
  color: var(--muted);
}

.runtime-list {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0 14px 14px;
}

.runtime-list div {
  display: grid;
  grid-template-columns: 130px 1fr;
  gap: 10px;
  padding: 8px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.045);
}

.runtime-list dt {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.runtime-list dd {
  margin: 0;
  font-family: var(--mono);
  font-size: 9px;
  color: var(--muted);
  overflow-wrap: anywhere;
}

.runtime-list code {
  color: var(--lime);
  font-size: 8px;
}

.blocker-list {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 0 14px 14px;
}

.blocker-list > div {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 9px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.045);
  color: var(--amber);
}

.blocker-list span {
  font-size: 10px;
  color: var(--muted);
}

.blocker-list strong {
  color: var(--text);
  font-weight: 500;
}

.endpoint-links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 0 14px 14px;
}

.endpoint-links a {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 8px;
  border: 1px solid var(--line);
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted);
}

.endpoint-links a:hover {
  color: var(--lime);
  border-color: rgba(189, 244, 111, 0.3);
}

/* ---------- misc ---------- */

.load-error {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  padding: 10px 12px;
  border: 1px solid rgba(255, 115, 115, 0.3);
  border-radius: 5px;
  background: rgba(255, 115, 115, 0.05);
  color: var(--red);
}

.load-error p {
  margin: 1px 0 0;
  font-size: 10px;
  color: var(--muted);
}

.load-error button {
  margin-left: auto;
  padding: 5px 9px;
  border: 1px solid rgba(255, 115, 115, 0.3);
  border-radius: 3px;
  background: transparent;
  color: var(--red);
  font-family: var(--mono);
  font-size: 8px;
}

.boot-panel {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 300px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
}

.boot-scan {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--lime), transparent);
  animation: scan 2s linear infinite;
}

.foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 18px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  font-family: var(--mono);
  font-size: 7.5px;
  color: var(--muted-2);
}

.toast {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 80;
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: 440px;
  padding: 11px 13px;
  border: 1px solid var(--line-strong);
  border-radius: 5px;
  background: #101923;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.5);
  font-size: 11px;
  animation: toast-in 180ms ease-out;
}

.toast-ok {
  border-color: rgba(88, 224, 192, 0.35);
}
.toast-error {
  border-color: rgba(255, 115, 115, 0.4);
}
.toast-info {
  border-color: rgba(189, 244, 111, 0.28);
}

.toast button {
  display: grid;
  place-items: center;
  flex: none;
  padding: 3px;
  border: 0;
  border-radius: 3px;
  background: transparent;
  color: var(--muted);
}

.toast button:hover {
  background: rgba(255, 255, 255, 0.07);
  color: var(--text);
}

.compact-summary {
  font-family: var(--mono);
  font-size: 8px;
  color: var(--muted-2);
}

.spin {
  animation: spin 1s linear infinite;
}

