import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    include: ["tests/**/*.test.ts"],
    environment: "node",
    testTimeout: 15_000,
    hookTimeout: 15_000,
    restoreMocks: true,
  },
});

import type {
  Prospect,
  ResearchInput,
  ResearchResult,
  SourceReference,
} from "../shared/types.ts";
import type {
  ResearchContext,
  ResearchProvider,
} from "../server/research/liveResearch.ts";
import { ResearchExecutionError } from "../server/research/liveResearch.ts";

export function buildSource(
  id: string,
  kind: SourceReference["kind"],
  url: string,
  retrievedAt: string,
): SourceReference {
  return {
    id,
    kind,
    title: `${kind} source ${id}`,
    url,
    publisher: "Test fixture",
    retrievedAt,
    excerpt: `Observed evidence for ${id}`,
    contentHash: "a".repeat(64),
  };
}

export function buildProspect(index: number, timestamp: string): Prospect {
  const pid = `PRS-TEST-${index + 1}`;
  const osm = buildSource(
    `${pid}-OSM`,
    "OPENSTREETMAP",
    `https://www.openstreetmap.org/node/${1000 + index}`,
    timestamp,
  );
  const web = buildSource(
    `${pid}-WEB`,
    "WEBSITE",
    `https://example-${index + 1}.test`,
    timestamp,
  );
  const website = {
    url: web.url,
    domain: `example-${index + 1}.test`,
    verification: "PAGE_VERIFIED" as const,
    httpStatus: 200,
    finalUrl: web.url,
    https: true,
    title: `Test Business ${index + 1}`,
    description: null,
    responseMs: 120,
    contentHash: "b".repeat(64),
    audit: {
      viewport: false,
      metaDescription: null,
      h1: `Test Business ${index + 1}`,
      socialLinks: [],
      bookingLinks: [],
      structuredData: false,
      copyrightYear: 2019,
      generator: null,
      forms: 0,
      phoneLinks: 0,
      pageBytes: 2048,
      contentType: "text/html",
      serverHeader: "test",
      titleMatch: "STRONG" as const,
    },
    notes: [],
  };
  return {
    id: pid,
    rank: index + 1,
    businessName: `Test Business ${index + 1}`,
    category: "café",
    location: {
      address: `${index + 1} Test Street`,
      city: "Testville",
      country: "Ireland",
      lat: 53.27 + index * 0.001,
      lon: -9.05,
    },
    osm: { type: "node", id: 1000 + index, url: osm.url },
    website,
    opportunity: {
      level: "HIGH",
      score: 82,
      summary: "Observed technical refresh opportunity: no mobile viewport.",
      signals: [
        {
          code: "NO_VIEWPORT",
          label: "No mobile viewport meta tag",
          impact: 25,
          evidence: "The homepage HTML does not declare a responsive viewport.",
          sourceRefs: [`${pid}-WEB`],
        },
      ],
    },
    facts: [
      {
        statement: `OpenStreetMap lists Test Business ${index + 1}.`,
        sourceRefs: [`${pid}-OSM`],
      },
    ],
    assumptions: ["Owner intent is unknown."],
    sources: [osm, web],
    researchTimestamp: timestamp,
  };
}

export function buildResult(
  input: ResearchInput,
  timestamp: string,
): ResearchResult {
  const prospects = Array.from({ length: input.count }, (_, index) =>
    buildProspect(index, timestamp),
  );
  return {
    assignment: {
      city: input.city,
      category: input.category,
      requestedCount: input.count,
      deliveredCount: input.count,
    },
    prospects,
    methodology: ["Test method"],
    limitations: ["Test limitation"],
    sources: [
      buildSource(
        "SRC-CITY",
        "NOMINATIM",
        "https://nominatim.openstreetmap.org/",
        timestamp,
      ),
      ...prospects.flatMap((prospect) => prospect.sources),
    ],
    executedAt: timestamp,
    provider: "test-provider",
    candidatesExamined: input.count + 2,
    websitesAudited: input.count + 2,
  };
}

export class FakeResearchProvider implements ResearchProvider {
  readonly name = "test-provider";
  calls = 0;
  failNext = 0;

  async execute(
    input: ResearchInput,
    context: ResearchContext,
  ): Promise<ResearchResult> {
    this.calls += 1;
    await context.onProgress("AUDIT", "Fake provider auditing.", 50);
    if (this.failNext > 0) {
      this.failNext -= 1;
      throw new ResearchExecutionError(
        "UPSTREAM_UNAVAILABLE",
        "A required open-data service could not be reached.",
        "Simulated upstream timeout.",
        true,
      );
    }
    return buildResult(input, new Date().toISOString());
  }
}

export async function waitFor(
  predicate: () => Promise<boolean> | boolean,
  timeoutMs = 5_000,
  intervalMs = 20,
): Promise<void> {
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    if (await predicate()) return;
    await new Promise((resolve) => setTimeout(resolve, intervalMs));
  }
  throw new Error(`Condition not met within ${timeoutMs}ms`);
}

import { describe, expect, it, beforeEach } from "vitest";
import request from "supertest";
import type { Response } from "express";
import type { Task } from "../shared/types.ts";
import { createApp } from "../server/app.ts";
import { HqBus } from "../server/bus.ts";
import { HqRunner } from "../server/runner.ts";
import { TaskStore } from "../server/store.ts";
import { FakeResearchProvider, waitFor } from "./helpers.ts";

interface Harness {
  store: TaskStore;
  bus: HqBus;
  provider: FakeResearchProvider;
  runner: HqRunner;
  app: ReturnType<typeof createApp>;
}

async function harness(store?: TaskStore): Promise<Harness> {
  const taskStore = store ?? new TaskStore(null);
  await taskStore.init();
  const bus = new HqBus();
  const provider = new FakeResearchProvider();
  const runner = new HqRunner({
    store: taskStore,
    provider,
    bus,
    mode: "TEST",
  });
  const app = createApp({
    store: taskStore,
    runner,
    bus,
    version: "test",
    startedAt: new Date().toISOString(),
    researchProvider: provider.name,
    enableRateLimit: false,
    staticDir: null,
  });
  return { store: taskStore, bus, provider, runner, app };
}

async function getTask(app: Harness["app"], id: string): Promise<Task> {
  const response = await request(app).get(`/api/tasks/${id}`);
  expect(response.status).toBe(200);
  return response.body.task as Task;
}

async function waitForStatus(
  app: Harness["app"],
  id: string,
  status: Task["status"],
): Promise<Task> {
  let latest: Task | null = null;
  await waitFor(async () => {
    latest = await getTask(app, id);
    return latest.status === status;
  });
  return latest as Task;
}

async function submit(
  h: Harness,
  overrides: Record<string, unknown> = {},
): Promise<Task> {
  const response = await request(h.app)
    .post("/api/tasks/research")
    .send({ city: "Galway, Ireland", category: "cafe", count: 3, ...overrides });
  expect(response.status).toBe(202);
  return response.body.task as Task;
}

describe("research task submission and execution", () => {
  let h: Harness;

  beforeEach(async () => {
    h = await harness();
  });

  it("rejects invalid submissions with a useful error", async () => {
    const shortCity = await request(h.app)
      .post("/api/tasks/research")
      .send({ city: "A", category: "cafe", count: 3 });
    expect(shortCity.status).toBe(400);
    expect(shortCity.body.error.code).toBe("INVALID_INPUT");

    const badCategory = await request(h.app)
      .post("/api/tasks/research")
      .send({ city: "Galway", category: "casino", count: 3 });
    expect(badCategory.status).toBe(400);

    const badCount = await request(h.app)
      .post("/api/tasks/research")
      .send({ city: "Galway", category: "cafe", count: 9 });
    expect(badCount.status).toBe(400);

    const missing = await request(h.app).get("/api/tasks/TSK-NOPE");
    expect(missing.status).toBe(404);
    expect(missing.body.error.code).toBe("TASK_NOT_FOUND");
  });

  it("queues, executes, verifies delivery, and serves the stored result", async () => {
    const accepted = await submit(h);
    expect(accepted.status).toBe("QUEUED");
    expect(accepted.execution.mode).toBe("TEST");

    const completed = await waitForStatus(h.app, accepted.id, "COMPLETED");
    expect(completed.startedAt).toBeTruthy();
    expect(completed.completedAt).toBeTruthy();
    expect(completed.delivery.persisted).toBe(true);
    expect(completed.delivery.readbackVerified).toBe(true);
    expect(completed.delivery.verifiedAt).toBeTruthy();
    expect(completed.delivery.apiPath).toBe(`/api/tasks/${accepted.id}`);
    expect(completed.error).toBeNull();

    expect(completed.result).not.toBeNull();
    if (!completed.result || !("prospects" in completed.result)) {
      throw new Error("Expected a research result");
    }
    expect(completed.result.prospects).toHaveLength(3);
    expect(completed.result.prospects[0].sources.length).toBeGreaterThan(0);
    expect(
      completed.events.some((event) => event.status === "QUEUED"),
    ).toBe(true);
    expect(
      completed.events.some((event) => event.status === "RUNNING"),
    ).toBe(true);
    expect(
      completed.events.some((event) => event.kind === "DELIVERY"),
    ).toBe(true);
    expect(h.provider.calls).toBe(1);

    const apiResponse = await request(h.app).get(`/api/tasks/${accepted.id}`);
    expect(apiResponse.status).toBe(200);
    expect(apiResponse.body.task.status).toBe("COMPLETED");
    expect(apiResponse.body.task.result.prospects).toHaveLength(3);

    const disk = await h.store.readFromDisk(accepted.id);
    expect(disk?.status).toBe("COMPLETED");
    expect(disk?.result).not.toBeNull();
  });

  it("keeps a failure visible and retries it successfully", async () => {
    h.provider.failNext = 1;
    const accepted = await submit(h, { count: 2 });
    const failed = await waitForStatus(h.app, accepted.id, "FAILED");

    expect(failed.error).not.toBeNull();
    expect(failed.error?.code).toBe("UPSTREAM_UNAVAILABLE");
    expect(failed.error?.retryable).toBe(true);
    expect(failed.error?.detail).toContain("Simulated upstream timeout");
    expect(failed.result).toBeNull();
    expect(failed.delivery.readbackVerified).toBe(false);
    expect(failed.progress.stage).toBe("FAILED");

    const retried = await request(h.app).post(
      `/api/tasks/${accepted.id}/retry`,
    );
    expect(retried.status).toBe(202);
    expect(retried.body.task.status).toBe("QUEUED");
    expect(retried.body.task.error).toBeNull();

    const completed = await waitForStatus(h.app, accepted.id, "COMPLETED");
    expect(completed.execution.attemptedPasses).toBe(2);
    expect(completed.completedAt).toBeTruthy();
    expect(h.provider.calls).toBe(2);
  });

  it("does not allow retry of a non-failed task", async () => {
    const accepted = await submit(h, { count: 1 });
    const response = await request(h.app).post(
      `/api/tasks/${accepted.id}/retry`,
    );
    expect(response.status).toBe(409);
    expect(response.body.error.code).toBe("TASK_NOT_RETRYABLE");
  });
});

describe("delivery verification", () => {
  it("fails instead of reporting COMPLETED when read-back does not match", async () => {
    class BrokenReadbackStore extends TaskStore {
      async readFromDisk(): Promise<Task | null> {
        return null;
      }
    }
    const store = new BrokenReadbackStore(null);
    const h = await harness(store);
    const accepted = await submit(h, { count: 1 });
    const failed = await waitForStatus(h.app, accepted.id, "FAILED");

    expect(failed.error?.code).toBe("DELIVERY_UNVERIFIED");
    expect(failed.delivery.readbackVerified).toBe(false);
    expect(failed.result).toBeNull();
    expect(failed.status).not.toBe("COMPLETED");
  });
});

describe("approval gate", () => {
  let h: Harness;
  let completed: Task;
  let prospectId: string;

  beforeEach(async () => {
    h = await harness();
    const accepted = await submit(h, { count: 1 });
    completed = await waitForStatus(h.app, accepted.id, "COMPLETED");
    const result = completed.result;
    if (!result || !("prospects" in result)) {
      throw new Error("Expected a research result");
    }
    prospectId = result.prospects[0].id;
  });

  it("creates an AWAITING_APPROVAL draft and only completes on approval", async () => {
    const created = await request(h.app).post("/api/tasks/outreach").send({
      parentTaskId: completed.id,
      prospectId,
    });
    expect(created.status).toBe(201);
    const draftTask = created.body.task as Task;
    expect(draftTask.status).toBe("AWAITING_APPROVAL");
    expect(draftTask.result).not.toBeNull();
    if (!draftTask.result || !("draft" in draftTask.result)) {
      throw new Error("Expected an outreach draft");
    }
    expect(draftTask.result.sent).toBe(false);
    expect(draftTask.result.draft.body).toContain("Nothing has been sent");
    expect(draftTask.approval?.status).toBe("PENDING");
    expect(draftTask.delivery.readbackVerified).toBe(true);

    const approved = await request(h.app)
      .post(`/api/tasks/${draftTask.id}/decision`)
      .send({ decision: "APPROVE", note: "Looks accurate." });
    expect(approved.status).toBe(200);
    expect(approved.body.task.status).toBe("COMPLETED");
    expect(approved.body.task.approval.status).toBe("APPROVED");
    expect(approved.body.task.approval.note).toBe("Looks accurate.");
    expect(approved.body.task.result.sent).toBe(false);
    expect(
      approved.body.task.events.some((event: { message: string }) =>
        event.message.includes("nothing was sent"),
      ),
    ).toBe(true);

    const again = await request(h.app)
      .post(`/api/tasks/${draftTask.id}/decision`)
      .send({ decision: "APPROVE" });
    expect(again.status).toBe(409);
    expect(again.body.error.code).toBe("NO_PENDING_APPROVAL");
  });

  it("marks a rejected draft FAILED and blocks retry", async () => {
    const created = await request(h.app).post("/api/tasks/outreach").send({
      parentTaskId: completed.id,
      prospectId,
    });
    const draftTask = created.body.task as Task;

    const rejected = await request(h.app)
      .post(`/api/tasks/${draftTask.id}/decision`)
      .send({ decision: "REJECT", note: "Tone is wrong." });
    expect(rejected.status).toBe(200);
    expect(rejected.body.task.status).toBe("FAILED");
    expect(rejected.body.task.error.code).toBe("REJECTED_BY_OPERATOR");
    expect(rejected.body.task.error.retryable).toBe(false);

    const retry = await request(h.app).post(
      `/api/tasks/${draftTask.id}/retry`,
    );
    expect(retry.status).toBe(409);
  });

  it("rejects outreach for a prospect outside the parent task", async () => {
    const response = await request(h.app).post("/api/tasks/outreach").send({
      parentTaskId: completed.id,
      prospectId: "PRS-NOT-REAL",
    });
    expect(response.status).toBe(404);
    expect(response.body.error.code).toBe("PROSPECT_NOT_FOUND");
  });
});

describe("interface delivery stream", () => {
  it("broadcasts the full task record to subscribed clients", async () => {
    const h = await harness();
    const accepted = await submit(h, { count: 1 });
    const chunks: string[] = [];
    const fakeResponse = {
      write: (chunk: string) => {
        chunks.push(chunk);
        return true;
      },
      end: () => undefined,
    } as unknown as Response;

    const unsubscribe = h.bus.subscribe(fakeResponse);
    expect(h.bus.clientCount).toBe(1);
    const delivered = h.bus.broadcastTask(accepted);
    expect(delivered).toBe(1);
    expect(chunks.join("")).toContain("event: task");
    expect(chunks.join("")).toContain(accepted.id);
    unsubscribe();
    expect(h.bus.clientCount).toBe(0);
  });

  it("serves an initial SSE snapshot over HTTP", async () => {
    const h = await harness();
    const accepted = await submit(h, { count: 1 });
    const server = h.app.listen(0);
    const address = server.address();
    if (!address || typeof address === "string") {
      throw new Error("Could not bind test server");
    }
    const controller = new AbortController();
    try {
      const response = await fetch(
        `http://127.0.0.1:${address.port}/api/events`,
        { signal: controller.signal },
      );
      expect(response.status).toBe(200);
      expect(response.headers.get("content-type")).toContain(
        "text/event-stream",
      );
      const reader = response.body?.getReader();
      if (!reader) throw new Error("No SSE body");
      const decoder = new TextDecoder();
      let text = "";
      const deadline = Date.now() + 3_000;
      while (!text.includes("event: snapshot") && Date.now() < deadline) {
        const { value, done } = await reader.read();
        if (done) break;
        text += decoder.decode(value, { stream: true });
      }
      expect(text).toContain("event: snapshot");
      expect(text).toContain(accepted.id);
    } finally {
      controller.abort();
      server.close();
    }
  });
});

import { describe, expect, it } from "vitest";
import {
  auditHtml,
  buildOpportunity,
  decodeEntities,
  extractMeta,
  extractTitle,
  stripTags,
} from "../server/research/extract.ts";
import { FetchSafetyError, isPrivateAddress, safeFetch } from "../server/research/http.ts";
import type { WebsiteFinding } from "../shared/types.ts";

const HTML = `<!doctype html>
<html>
  <head>
    <title>Bean There Café &amp; Bakery</title>
    <meta property="og:title" content="Bean There" />
  </head>
  <body>
    <h1>Bean There Café</h1>
    <p>Independent coffee on Market Street.</p>
    <footer>&copy; 2020 Bean There</footer>
  </body>
</html>`;

function page(overrides: Partial<WebsiteFinding> = {}): WebsiteFinding {
  return {
    url: "https://bean.example",
    domain: "bean.example",
    verification: "PAGE_VERIFIED",
    httpStatus: 200,
    finalUrl: "https://bean.example",
    https: true,
    title: "Bean There Café",
    description: null,
    responseMs: 300,
    contentHash: "c".repeat(64),
    audit: null,
    notes: [],
    ...overrides,
  };
}

describe("HTML extraction", () => {
  it("extracts and decodes titles, meta values, and text", () => {
    expect(extractTitle(HTML)).toBe("Bean There Café & Bakery");
    expect(extractMeta(HTML, "og:title")).toBe("Bean There");
    expect(extractMeta(HTML, "description")).toBeNull();
    expect(stripTags("<p>Hello&nbsp;<strong>world</strong></p>")).toBe(
      "Hello world",
    );
    expect(decodeEntities("A &#38; B &#x26; C")).toBe("A & B & C");
  });

  it("records only observable homepage signals", () => {
    const audit = auditHtml(HTML, "Bean There Café", "text/html", "nginx", 4096);
    expect(audit.viewport).toBe(false);
    expect(audit.metaDescription).toBeNull();
    expect(audit.h1).toBe("Bean There Café");
    expect(audit.socialLinks).toEqual([]);
    expect(audit.bookingLinks).toEqual([]);
    expect(audit.structuredData).toBe(false);
    expect(audit.copyrightYear).toBe(2020);
    expect(audit.serverHeader).toBe("nginx");
    expect(audit.titleMatch).toBe("STRONG");
  });

  it("scores a stale, non-responsive homepage as high opportunity", () => {
    const audit = auditHtml(HTML, "Bean There Café", "text/html", "nginx", 4096);
    const website = page({ audit });
    const opportunity = buildOpportunity(
      website,
      3200,
      { website: "WEB", osm: "OSM" },
      2026,
    );
    expect(opportunity.level).toBe("HIGH");
    expect(opportunity.score).toBe(100);
    const codes = opportunity.signals.map((signal) => signal.code);
    expect(codes).toContain("NO_VIEWPORT");
    expect(codes).toContain("NO_META_DESCRIPTION");
    expect(codes).toContain("STALE_COPYRIGHT");
    expect(codes).toContain("SLOW_RESPONSE");
    expect(opportunity.summary).toContain("observed technical refresh opportunity");
    for (const signal of opportunity.signals) {
      expect(signal.sourceRefs.length).toBeGreaterThan(0);
    }
  });

  it("flags plain HTTP and identity mismatch", () => {
    const audit = auditHtml(HTML, "Different Company", "text/html", null, 4096);
    const website = page({
      url: "http://bean.example",
      finalUrl: "http://bean.example",
      https: false,
      audit,
    });
    const opportunity = buildOpportunity(
      website,
      200,
      { website: "WEB", osm: "OSM" },
      2026,
    );
    const codes = opportunity.signals.map((signal) => signal.code);
    expect(codes).toContain("NO_HTTPS");
    expect(codes).toContain("IDENTITY_UNCLEAR");
    expect(audit.titleMatch).toBe("NONE");
  });

  it("reports an unreachable website as evidence, not a fabricated page", () => {
    const website = page({
      verification: "UNREACHABLE",
      httpStatus: 503,
      finalUrl: null,
      audit: null,
      notes: ["The official website returned HTTP 503."],
    });
    const opportunity = buildOpportunity(
      website,
      null,
      { website: "WEB", osm: "OSM" },
      2026,
    );
    expect(opportunity.signals[0].code).toBe("WEBSITE_UNREACHABLE");
    expect(opportunity.signals[0].evidence).toContain("503");
  });
});

describe("network safety", () => {
  it("identifies private and reserved addresses", () => {
    expect(isPrivateAddress("127.0.0.1")).toBe(true);
    expect(isPrivateAddress("10.2.3.4")).toBe(true);
    expect(isPrivateAddress("172.20.1.1")).toBe(true);
    expect(isPrivateAddress("192.168.0.1")).toBe(true);
    expect(isPrivateAddress("169.254.1.2")).toBe(true);
    expect(isPrivateAddress("::1")).toBe(true);
    expect(isPrivateAddress("fd00::1")).toBe(true);
    expect(isPrivateAddress("8.8.8.8")).toBe(false);
    expect(isPrivateAddress("1.1.1.1")).toBe(false);
  });

  it("blocks localhost before making a request", async () => {
    await expect(safeFetch("http://127.0.0.1:3999")).rejects.toBeInstanceOf(
      FetchSafetyError,
    );
    await expect(safeFetch("http://localhost:3999")).rejects.toBeInstanceOf(
      FetchSafetyError,
    );
    await expect(safeFetch("file:///etc/passwd")).rejects.toBeInstanceOf(
      FetchSafetyError,
    );
  });
});

